  MemoryStory(
    slug: 'brilletje-1461',
    title: 'Brilletje',
    narrator: 'Tineke de Ruyter',
    author: 'Tineke de Ruyter',
    theme: 'school',
    neighbourhood: 'Hart van Heemskerk',
    period: '1949',
    intro: ['Toen ik op de kleuterschool zat moest ik voor het eerst een bril gaan dragen. Dat was niet leuk...'],
    body: ['Ik ging in 1949 als vijfjarig meisje voor het eerst naar de kleuterschool, toen nog bewaarschool genoemd. Deze school was ondergebracht in aantal lokalen van de Mariaschool, en werd geleid door nonnetjes. Het waren grote klassen, zo tussen de 40 en 50 kinderen per klas. Ik had al van mijn oudere broer en zusje gehoord dat zuster Mathea een kreng was, daar moest je niet bij terecht komen. Zij hadden allebei bij zuster Lutgardus gezeten, en meestal kwamen de kinderen uit één gezin bij dezelfde juf of zuster, dus dat zat wel goed dacht ik. Maar ik werd ingedeeld bij een juffrouw (ik weet haar naam niet meer), die nog niet volledig bevoegd was. Eén dag in de week moest ze nog naar school en dan werden wij verdeeld over de andere, toch al grote klassen. En ik kwam bij zuster Mathea.', 'Er was op de kleuterschool gebleken dat ik niet zo goed kon zien, dus naar de oogarts en een brilletje. Een ziekenfondsbrilletje werd dat genoemd. Vreeeselijk.', 'De dag dat we weer naar zuter Mathea moesten wilde ik ook naar binnen, de klas in. Maar ze hield me tegen. “Dit vreemde meisje hoort hier niet”. Ze plukte me uit de rij en zette me bruusk tegen de w.c-deur in de gang. De rest mocht wel naar binnen. Huilen natuurlijk, maar wat ik ook zei, ik moest daar blijven staan. Gelukkig probeerden andere kinderen haar ook te overtuigen en toen mocht ik opeens wél naar binnen. Maar toen had ze het al voor goed verbruid bij me.', 'Verhaal verteld op: 01-09-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1464-490-799-1.jpg', caption: 'Op de kleuterschool, toen nog "bewaarschool" genoemd, gevestigd in de Mariaschool.')],
    relatedSlugs: ['slapen-tussen-kippengaas-1992', 'dodenherdenking-5263', 'paasbest-5015', 'nonnenfrustratie-1658', 'ik-timmerde-hem-op-zijn-neus-1421', 'ik-belde-mijn-kinderen-moeder-gaat-weer-naar-schoo-3118'],
  ),
  MemoryStory(
    slug: 'burgemeester-gesnapt-3463',
    title: 'Burgemeester gesnapt',
    narrator: 'Jeanne Castricum - de Wit',
    author: 'Jeanne Castricum',
    theme: 'bekende personen',
    neighbourhood: 'Hart van Heemskerk',
    period: '2007',
    intro: ['Muziek is de taal die iedereen verstaat. Om 10.00 uur is de fanfare aanwezig in het dorp. Er staan twee lieftallige meisjes op het Kerkplein. Hun haren zijn met oranje streepjes gekleurd, ze spelen op de viool met de strijkstokjes zo sierlijk. Daar moet ik echt een foto van maken.'],
    body: ['Terwijl ik deze foto neem komt er een man aanlopen, hij gooit wat geld in de vioolkist en gaat tussen deze meisjes in staan. \\"Zal dat hun vader of misschien hun opa zijn?\\"vraag ik me af. De man steekt zijn hand in zijn broekzak en haalt er iets glinsterends uit. Het blijkt een ketting te zijn. Hij hangt de ketting om zijn nek en tot mijn verbazing maak ik zomaar een foto van onze nieuwe burgermeester op deze Koninginnedag.', 'Verhaal verteld op: 30-04-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3539-490-714-1.jpg', caption: 'Twee lieftallige violistes samen met de nieuwe burgemeester Nawijn.')],
    relatedSlugs: ['eerste-deuntje-3046', 'radiotik-2888', 'muziek-op-het-kerkplein-2298', 'drie-gezichten-van-sint-en-piet-4349', 'dodenherdenking-5263', 'de-smederij-van-piet-van-t-hoekie-2745'],
