  MemoryStory(
    slug: 'eens-was-er-carnaval-in-heemskerk-2315',
    title: 'Eens was er carnaval in Heemskerk',
    narrator: 'Corrie Beentjes',
    author: 'Loes Sprengers',
    theme: 'feesten & evenementen',
    neighbourhood: 'Hart van Heemskerk',
    period: '1965 - 1975',
    intro: ['Carnaval is gevierd, "Pieperduin" mag weer Castricum zijn. Eens hadden wij in Heemskerk "de Propeppers" met Prins Carnaval, de Raad van Elf, praalwagens en feest in de "Dr. Prinsenhal". Heemskerk werd "Ezelenheem" en deed mee aan Carnaval.'],
    body: ['Waar wij mee bezig waren had niets met "de Propeppers" te maken maar hoe het nou precies begon?', 'Wij kwamen al gewoon met een groepje vrienden een keer of vier per jaar bij elkaar in café \'Halfweg\' daar op het Hofland. Een borreltje, bijpraten, een beetje lol maken. Wij kenden de eigenaren, het was er oergezellig! Ooit zal het woord \'carnaval\'gevallen zijn want op een gegeven moment werden plannen gemaakt en naar een soort hoogtepunt rond carnaval toegewerkt, waar je dan meer of minder verkleed naar toe ging. Het had meer weg van gekostumeerde bruiloft in carnavalstijl maar wij vierden feest, zakten lekker door. Een drankje kon je kopen met consumptiebonnen. De contributie werd gebruikt voor de onkosten. Een duo met accordeon en drumstel zorgde voor muziek. En dan; handjes omhoog, "Alaaf" en de voetjes van de vloer, gewoon een dolle boel. Maar wij zijn er wel vanaf het begin bij geweeest en ja, had het nou een naam?', 'Er kwamen méér bekenden, "Halfweg" werd te klein, toen moest uitgeweken worden naar speeltuingebouwtje "Flipper". Later nog naar "de Snip". Carnavalfeest werd gevierd met een complete prins in gehuurd pak want het was een arme club. Zelfs kindermiddagen waren er en leuke kostuumcreaties bedacht en gemaakt. De mooiste en origineelste kregen een prijs. Soms was iemand zo gecamoufleerd dat hij/zij voor een ander werd aangekeken wat leuk uitpakte bij de ontmaskering aan het eind van de avond. Het was wel lachen!', 'Jammer het hield geen stand. Er stroomde meer kermisbloed in de aderen van de Heemskerkers en het carnavalsgebeuren kreeg last van de malaise en dus einde polonaise.', 'Verhaal verteld op: 03-03-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2333-490-697-1.jpg', caption: 'Carnavalsprins Martien Beentjes')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'eerste-deuntje-3046', 'dodenherdenking-5263', 'muziek-op-het-kerkplein-2298', 'sport-en-spel-bij-de-cornelis-geelvinckstraat-5154', 'radiotik-2888'],
  ),
  MemoryStory(
    slug: 'eerste-deuntje-3046',
    title: 'Eerste deuntje',
    narrator: 'Jeanne Castricum',
    author: 'Jeanne Castricum',
    theme: 'feesten & evenementen',
    neighbourhood: 'Hart van Heemskerk',
    period: '1900 - 2006',
    intro: ['De kermis dat is een echte happening, veel jongelui trekken naar het dorp.'],
    body: ['Er klinkt al vrolijke muziek en er heerst een gezellige stemming op straat. Bij de Jansheeren spelen de IJmond Players en er wordt in stijl gedanst.', 'Later verandert het in feeststemming.', 'Ik zie Ben Kuyt met Nel binnen komen, de kermisfotograaf die een plaatje schiet. Dit werk doet hij al 40 jaar, en Nel 20 jaar, en met veel plezier. Deze twee mensen horen bij de kermis. Terwijl ik dit duo even kiek wordt er volop gedanst en velen omhelsen elkaar innig bij het weerzien.', 'Even later spreek ik Klaas. Hij moest even een boodschap doen in het dorp, vertelt hij, maar de gezelligheid trok hem naar de Jansheeren. Hij heeft wel eerst bij Zeeman een overhemd gekocht voor 4 Eurootjes. Daarmee is Klaas dressed-up en ready to go. Het klusje thuis kan wel even wachten. Hij is de bink bij de dames. Druk aan het swingen als Elvis Presly op muziek van Bonna Sera.', 'Gezelligheid en volop vrolijkheid bij de bar met een koel pilsje van de tap. Mevrouw Duin komt huppelend naar mij toe, ze geniet alsof ze 18 is. Ze vertelt dat ze het reuze gezellig vindt. Wat is het leuk om je weer jong te voelen en mensen te zien genieten.', 'De stijl gaat over in hossen en polonaise. Een moeder duwt een rolstoel, waar zoon Daan in zit, op de maat van de muziek met de polonaise mee. Wat kan een dag voor iemand veel betekenen.', '\'Wat is het leven mooi, als de zon schijnt\' wordt luidkeels meegezongen.', 'Mensen die buiten Heemskerk wonen en die in de Jansheeren om de veertien dagen komen om te dansen, zijn vrolijk en de handjes gaan de lucht in en de remmen los.', 'Ik zie mevrouw en meneer Welp innig handje in handje naar hun plaatsje lopen. Wat zouden hun kinderen genieten van dit moment van hun ouders.', 'En dan ga ik de Jansheeren verlaten.', 'Ik loop tussen de feestgangers in het dorp en hoor het gekraak van plastic bekertjes onder mijn voeten.', 'In de \'Amazone-tent\' klinkt voor de 20ste keer Corry Konings. De mensen zongen luidkeels mee met \'Mooi was die tijd\', de handen in een wave naar boven gericht.', 'Met de muziek van \'Paradise\', de wereldhit van Bon Jovi \'I like to lay down on a bed of roses\' sluit de kermis in Heemskerk af.', 'Verhaal verteld op: 08-02-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3119-490-334-1.jpg', caption: 'Ben en Nel Kuyt')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'muziek-op-het-kerkplein-2298', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472'],
  ),
  MemoryStory(
    slug: 'ehbo-vereniging-st-christophorus-4244',
    title: 'EHBO Vereniging St.Christophorus',
    narrator: 'Joop Sprengers',
    author: 'Jeanne Castricum',
    theme: 'vrijwilligerswerk',
    neighbourhood: 'Duin tot Dorp',
    period: '1952 - 1956',
    intro: ['Bij de Verkenners gebeurde nog wel eens een ongelukje en daarbij bleek dat de leiding niet altijd wist wat zij het beste kon doen. Zo onstond het idee om een jeugdcursus EHBO voor de verkenners te starten.'],
    body: ['Deze cursus was de aanleiding om in ons dorp een EHBO vereniging op te richten. Dat werd op 18 februari 1954 de Vereniging St.Christophorus. In een schoollokaal op de Oosterstreng werden de lessen gegeven door dokter Schutte. Daar werd met veel lol geoefend voor het diploma. Na het goed afleggen van het examen werden dan de diploma ‘s uitgereikt.', 'In 1956 had Jeanne de Wit net haar EHBO diploma gehaald toen er iets ernstigs gebeurde aan het strand. Haar vrienden zeiden nog lachend: "Kom op hier is een taak voor jou." Maar dit was geen spelletje. Zij begon met wat zij geleerd had toe te passen bij een drenkeling. Haar machteloosheid was groot toen een arts bij aankomst constateerde dat de eerste hulp die zij kon bieden tevergeefs was geweest.', 'Verhaal verteld op: 02-11-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4289-212-284-1.jpg', caption: 'EHBO diploma Joop Sprengers')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'verslaving-4346', 'slapen-tussen-kippengaas-1992', 'muziek-op-het-kerkplein-2298', 'de-smederij-van-piet-van-t-hoekie-2745', 'radiotik-2888'],
  ),
  MemoryStory(
    slug: 'elk-seizoen-een-keer-gestoken-5665',
    title: 'Elk seizoen één keer gestoken',
    narrator: 'Aad Wentink',
    author: 'Carla Wentink',
    theme: 'werk & werkloosheid',
    neighbourhood: '.',
    period: '',
    intro: ['Als plaagdierbestrijder bij ReinUnie ga ik voornamelijk op pad om plaagdieren zoals wespen, ratten, muizen of papiervisjes te bestrijden bij burgers thuis. Met wespen hebben wij het het drukst. Zeker in de zomerperiode.'],
    body: ['Ratten en muizen ruimen wij op met lokstoffen. Daar zit een gif in waar ze aan dood gaan. Voor de meeste andere plaagdieren moet je spuiten. Een beestje dat je steeds vaker ziet, is het papiervisje. Dit is een lastig beestje om te bestrijden. Het lijkt op een zilvervisje, maar dan iets donkerder van kleur. Hij houdt van droge plaatsen, zoals papier achter schilderijen. Daar graaft hij zich in. Om het papiervisje te bestrijden, spuiten wij in de naden en kieren. Vooral voor de mensen zelf is het bewerkelijk en vervelend. Zij moeten hun halve huis leeg halen, zodat wij overal bij kunnen.', 'Mijn werk bestaat verder uit preventieve controles bij bedrijven.', 'De middelen waarmee gewerkt wordt kunnen nogal eens veranderen omdat de wet steeds wijzigt. Heb je eindelijk iets gevonden dat goed werkt, moet je weer op zoek naar een ander middel. Maar het is altijd nog gelukt. Voor wespennesten moet ik wel eens vreemde capriolen uithalen, bijvoorbeeld op een schoorsteen klimmen of hard weglopen als je per ongeluk op een nest gaat staan. Een keer stoote ik bij het spuiten tegen een plank, waardoor het hele nest scheurde, ik heb wel vijf minuten in de tuin gestaan, met een zwerm woedende wespen om me heen. Of ik wel eens gestoken wordt? Een keertje per seizoen, zo ongeveer. Soms kruipt er toch eentje onder je pak. Maar dat hoort erbij.', 'Verhaal verteld op: 01-07-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.5748-490-368-1.jpg', caption: 'Dit is een verwijderd wespennest.')],
    relatedSlugs: ['verslaving-4346', 'emigreren-of-werken-op-kasteelhoeve-2243', 'landgoed-6201', 'het-witte-huisje-5783', 'als-hond-en-kat-4339', 'merkwaardig-4870'],
