  MemoryStory(
    slug: 'emigreren-of-werken-op-kasteelhoeve-2243',
    title: 'Emigreren of werken op kasteelhoeve',
    narrator: 'Wim Schavemaker',
    author: 'Kees van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Duin tot Dorp',
    period: '- 1949',
    intro: ['Als emigratie afketst wordt Wim (Willem) Schavemaker bedrijfsleider op Daantjeshof'],
    body: ['In de naoorlogse jaren emigreerden veel zoons van boeren en tuinders naar Amerika en Australië. De mogelijkheden om in Nederland een eigen bedrijf op te starten waren zeer beperkt. De Assendelver Wim Schavemaker die al enige tijd verkering had met de Heemskerkse tuidersdochter Annie Henneman wilde emigreren. Zijn moeder en schoonouders waren daar niet voor. Zij zouden hun kinderen nooit meer zien. Ten laatste werd besloten naar Frankrijk te emigreren. Niet zo ver. Terwijl de koffers al gepakt stonden kwam er een kink in de kabel. Voorlopig uitstel. Toen werd bekend dat Jonkheer Gevers een bedrijfsleider zocht op zijn boerderij nabij kasteel Marquette. Het sollicitatiegesprek vond plaats lopend over de oprijlaan naar het kasteel. Deze wandeling duurde 2 ½ uur. Jonkheer Daan Gevers had nog wat bedenktijd nodig doch de volgende ochtend om 8.00 uur was hij reeds ten huize Schavenmaker. Bijkomend voordeel was dat vrij spoedig getrouwd kon worden waardoor de boerderij Daantjeshof betrokken werd. Gevers was al in het bezit van 25 stuks zwart jong vee. Dit vee liep wel eens over naar het land van de buren. Gevers besloot eerst zijn weiland te voorzien van prikkeldraad omdat hij zijn eigen vee niet herkende tussen de koeien van de buren. Als oplossing werd bedacht om al zijn zwarte vee maar om te ruilen voor roodbont vee. Toen al deze koeien in korte tijd kalfden werd het tijd om een extra melkkracht aan te trekken. Buurman Joop de Munck kwam helpen melken. Uiteraard handmatig. De melk moest ’s-morgens vlak na 7 uur aan de weg staan om te worden opgehaald. Vroeg opstaan dus. Later kwam er een vaste medewerker. Echter die versliep zich regelmatig. Erg lastig voor Schavenmaker.', 'In 1957 kocht Schavemaker een boerderij in Assendelft en werd zelfstandig veehouder en pluimveehouder.', 'Verhaal verteld op: 25-01-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2247-490-368-1.jpg', caption: 'Links de hooiberging, midden de zogenaamde Duiventil, rechts voormalige woning.')],
    relatedSlugs: ['een-hoed-met-een-veertje-1469', 'het-witte-huisje-5783', 'ik-baalde-als-een-stekker-2048', 'ezel-met-duinkater-2036', 'van-marquette-bos-naar-hoogoven-5-1280', 'merkwaardig-4870'],
  ),
  MemoryStory(
    slug: 'ezel-met-duinkater-2036',
    title: 'Ezel met Duinkater',
    narrator: 'John Limmen',
    author: 'Linda van Zeijl',
    theme: 'liefde & huwelijk',
    neighbourhood: 'Duin tot Dorp',
    period: '1947 - 2006',
    intro: ['Ondanks mijn gebondenheid met het duin, ben ik nooit geaccepteerd door de duinkatten.'],
    body: ['Als geboren en (op)getogen Heemskerker koester ik de duinen als mijn achtertuintje. Niet alleen vanwege de natuur, maar vooral ook uit nostalgische overwegingen.', 'Vroeger gingen mijn broers en ik vaak met mijn vader mee naar de vrij gezellige kliek vrijgezellen, die onder het strenge regime van mijn tante het tuindersbedrijf aan de Voorweg in stand hielden.', 'Opgejut door de sterke verhalen van onze ooms aan de borreltafel probeerden wij een konijntje te verschalken, het prikkeldraad onderdoor en wegwezen! Spannend was dat, want er kon op elk ogenblik een koddebeier opduiken.', 'Ondanks mijn gebondenheid met het duin, ben ik nooit geaccepteerd door de duinkatten, alleen maar omdat ik aan de verkeerde kant van de Rijksstraatweg geboren ben. Ik heb er alles aan gedaan! Laat mij zelfs nog elke week vernederen door diezelfde duinkatten op de tennisbaan. Of ze niks anders te doen hebben dan de hele dag spelletjes te spelen!', 'Zomers lijkt de hele duinkant verhuisd te zijn naar het strand en in de winter hoor je aan de Luttik Cie de biljartballen klotsen. Voor de duidelijkheid, dit heeft niets met afgunst, jaloezie, neringziekte of p-nijd te maken!', 'Dus koop ik maar weer elk jaar een duinkaart uit angst voor de moderne koddebeier. Maar controleren?! Ik ren al jaar en dag met mijn steeds meer lawaaimakende knekels door de duinen, alleen kom ik nooit een dergelijk groen mannetje tegen. Wel de laatste tijd van die runderen, die het leuk vinden om met hun dikke lijven de kleinste paadjes te versperren. Opzij gaan? Ho maar, zelfs niet nadat ik ze met mijn beste Schotse accent probeer te overtuigen dat ik recht van overpad heb. Dus maar weer met mijn staart of zo tussen mijn benen een andere route zoeken en dat loopt erg lastig, kan ik je vertellen.', 'Echter nu mijn jongste nazaatje een duinkat is gaan daten, word ik eindelijk geaccepteerd of moet ik zeggen, getolereerd? Die twee samen hebben een nieuwe hobby, wat backpacken schijnt te heten. Ze zijn nu ergens in Zuid Afrika en hadden ons met de Kerst uitgenodigd om daar heen te komen en een route uitgestippeld naar het grootste duin ter wereld in Namibië. Wij hebben nu aan den lijve het backpackers leven mogen ervaren, wat ons wonderwel erg beviel.', 'Om hun ouders gerust te stellen over hun constant veranderende verblijfplaats hebben ze een website opgericht: www.erwinenmieke.waarbenjij.nu.', 'Zo zie je maar wat een echte Ezel allemaal moet doen om erbij te horen!!!!', 'Verhaal verteld op: 08-12-2005'],
    figures: [],
    relatedSlugs: ['snotneus-op-klompen-3154', 'verslaving-4346', 'een-grensgeval-1868', 'emigreren-of-werken-op-kasteelhoeve-2243', 'thuis-onder-de-toren-van-de-lau-1472', 'landgoed-6201'],
  ),
  MemoryStory(
    slug: 'fantasie-met-bomen-1627',
    title: 'Fantasie met bomen',
    narrator: 'Tiny van Dam',
    author: 'Nanny Schmidt',
    theme: 'straat & buurt',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '1963 - 2005',
    intro: ['"Ik was 13 jaar toen we in Heemskerk kwamen wonen. Mijn vader ging bij Hoogovens werken”. Aan het woord is Tiny van Dam (1950).'],
    body: ['Tijdens de lancering van het Geheugen van Heemskerk wandelde zij over het Burgemeester Nielenplein met één van haar kleinkinderen. Ze wilde best iets over Heemskerk vertellen op de Geheugenstoel. “We kwamen uit Alphen aan de Rijn hierheen. Ik zou daar nu niet meer naar terug willen. Heemskerk bevalt me prima hoewel het wel erg gegroeid is sinds die tijd.” Voor al die mensen die hier kwamen wonen, kwamen er nieuwe voorzieningen. Je kreeg hier bijvoorbeeld aardig wat buurthuizen. Tiny van Dam wist ze ook te vinden.', '“Begin jaren 80 en ook wel eerder had je altijd Dansen voor alleenstaanden in de Schuilhoek. Daar heb ik mijn man Theo leren kennen, waar ik nu negen jaar mee getrouwd ben. En er was tekenles bij Ewout van Santen. Daar ben ik een paar keer geweest. Van hem moest ik vooral bomen tekenen.', 'Later ging ik naar de Globe om te leren schilderen. Dinsdag ‘s morgens was daar Harm – ik weet niet hoe hij verder heet - en natuurlijk was er Ruud van Zon , die al jarenlang les geeft in de Heemskerkse buurthuizen. Ik teken eigenlijk altijd naar eigen fantasie. En stukje voor beetje bouw ik het schilderij op”. Een voorbeeld kreeg ik te zien toen ik later bij Tiny thuis langs ging. Tussen hoge bomen door zie je een klein dorpje in een duinachtige omgeving: het bomen tekenen dat Tiny in de Schuilhoek moest doen is toch nog goed van pas gekomen!'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1632-490-434-1.jpg', caption: 'Tiny van Dam schildert uit haar fantasie, na teken-en schilderlesssen in de Heemskerkse buurthuizen')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'emigreren-of-werken-op-kasteelhoeve-2243', 'landgoed-6201', 'muziek-op-het-kerkplein-2298', 'de-smederij-van-piet-van-t-hoekie-2745', 'ik-baalde-als-een-stekker-2048'],
  ),
  MemoryStory(
    slug: 'fazanten-lokken-met-anijs-1318',
    title: 'Fazanten lokken met anijs',
    narrator: 'Klaas van Maassen',
    author: 'Marjan Procee',
    theme: 'kastelen & landhuizen',
    neighbourhood: 'Duin tot Dorp',
    period: '1957 - 1963',
    intro: ['Klaas van Maassen was van 1957 tot 1963 bedrijfsleider van de boerderij op landgoed Marquette en organiseerde jaarlijks een jachtpartij.'],
    body: ['Jaarlijks werd er op het landgoed een jachtpartij georganiseerd. Voorbereidingen werden hiervoor getroffen onder andere door graan met anijs te vermengen. Dat werd op grote afstand geroken door de fazanten die daar op af kwamen. We zetten van te voren de plaatsen uit voor de jagers, legden planken over de sloten en dergelijke.', 'Er werden gasten uitgenodigd door jonkheer Gevers. Ik herinner mij nog de naam van baron van Tuyl en iemand van de koninklijke stallen.', 'Een aantal mensen uit Heemskerk werd als drijvers gevraagd mee te komen helpen. Meestal waren er vijf á zes geweren en een tiental drijvers. De buit bestond uit een aantal fazanten, eenden, houtsnippen, duiven en een paar hazen. Deze werden onderling verdeeld.', 'Verhaal verteld op: 01-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1320-490-339-1.jpg', caption: 'Klaas van Maassen in de rozentuin van Marquette')],
