  MemoryStory(
    slug: 'fietsenmaker-2647',
    title: 'Fietsenmaker',
    narrator: 'Nico Sinnige',
    author: 'Kees van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Duin tot Dorp',
    period: '1933 - 1940',
    intro: ['Nico sinnige mocht als jongste uit het gezin door gaan leren'],
    body: ['Fietsenmaker – Elektricien', 'Nick Sinnige was de jongste uit het gezin en mocht doorleren. Meester Gallee van de St.Jozefschool drong er op aan dat niet alle jongens tuinder of boer werden. Vader Sinnige zag wel toekomst in de opkomende autotechniek.Piet Kuil, de aardappelhandelaar zei: “Ik koop binnenkort een auto dus is het wel makkelijk als mijn zoon en jij Nick naar de ambachtschool gaan. Kunnen jullie die auto onderhouden”. Dus ging ik samen met Piet Kuil jr. op de fiets naar Castricum . Vandaar met de trein naar de Ambachtschool in Alkmaar. Na 3 jaar in 1933 behaalden we ons diploma.. Middenin de crisisjaren. Werk was er niet. In een klein schuurtje, een voormalig kalverenhok bij de ouderlijke woning, kon ik een kleine fietsenmakerij beginnen met steun van vader. De verkoop van nieuwe fietsen was heel beperkt en de voorraad bedroeg in het geheel één fiets. Ook werden bakfietsen verhuurd. In de avonduren ging ik nog doorleren. Elektriciteit was in opkomst. Ik behaalde ook deze diploma’s en werd ook elektricien met erkenning van de PEN. Zodoende kon ik ook elektriciteit aanleggen. Na de brand van de boerderij van Dirk Wenting had ik bij de nieuwbouw van boerderij Heemshof aan de Oosterweg een mooie klus. De verdiensten aan de verkoop van de apparatuur als lampen e.d. waren hoger als de verdiensten aan arbeidsloon. Het was toch al een grote klus. Ook kreeg ik het onderhoud aan het elektra in kasteel Assumburg. De houten balken waren keihard en erg hoog. Hoog op je ladder of trap moest je boren. Geen elektrische boren nog. De opkomst van het elektrisch koken zorgde ook nog voor wat verdiensten. De tijd bleef echter slecht en toen ik bij een bedrijf in Alkmaar kon komen werken omdat de eigenaar de nodige diploma’s ontbeerde ben ik daar gaan werken en wonen.', 'Verhaal verteld op: 15-06-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2649-490-328-1.jpg', caption: 'De verhuur van bakfietsen moest ook geld opleveren')],
    relatedSlugs: ['emigreren-of-werken-op-kasteelhoeve-2243', 'merkwaardig-4870', 'landgoed-6201', 'een-grensgeval-1868', 'ezel-met-duinkater-2036', 'van-marquette-bos-naar-hoogoven-5-1280'],
  ),
  MemoryStory(
    slug: 'fietsles-in-de-zandkraai-3766',
    title: 'Fietsles in de Zandkraai',
    narrator: 'Fatna Quotit',
    author: 'Luus de Wit',
    theme: 'verdwenen plekken',
    neighbourhood: 'Hart van Heemskerk',
    period: '1985 - 2007',
    intro: ['Midden jaren \'80 organiseerden Ingrid Lunter en Gré Laurens wekelijkse koffiemiddagen voor migrantenvrouwen in buurthuis de Zandkraai aan de Verherentstraat. Behalve koffie en thee drinken werd er wat afgepraat. En veel gebreid en patronen uitgewisseld.'],
    body: ['Ik was een van de trouwe bezoeksters van die middagen. Samen met een buurvrouw, net als ik Marokkaanse, had ik al geprobeerd te fietsen op veldjes in het Steenstrapark. Dat lukte natuurlijk niet. Op een dag begrepen we waarom. Een Nederlandse mevrouw vertelde ons dat fietsen op gras ook voor Nederlanders moeilijk is en ze adviseerde een andere plek te zoeken. We hadden het er natuurlijk over op de koffiemiddag en Safia en Malika stelden aan Ingrid voor om fietsles te organiseren. Ingrid regelde fietsen via Joop van Tunen, die zorgde ook dat de trappers werden verhoogd. Zo konden we er bij met onze korte benen.', 'Twee vrijwilligsters gaven ons fietsles en als het regende, leerden we banden plakken. Het fietsen ging al snel veel beter, maar nog niet op straat, want daar zijn regels en wie heeft er nu voorrang? Dus werd ook theorieles georganiseerd door autorijschool Klinger en wie de test doorstond kreeg van hen een certificaat. We oefenden ook met een pop achterop, maar die bewoog niet en woog bijna niets, dus ik heb uiteindelijk nooit met kinderen achterop gefietst. De fietsles was een succes en bestaat nog steeds in de Schuilhoek.', 'Verhaal verteld op: 04-03-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3770-490-654-1.jpg', caption: 'Vrijwilligster Karin Dijst helpt een deelneemster tijdens de fietsles op de skatebaan aan de Geelvinckstraat bij de Schuilhoek')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'burgemeester-gesnapt-3463', 'eerste-deuntje-3046', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472', 'de-buurtbus-een-heemskerks-sprookje-4205'],
  ),
  MemoryStory(
    slug: 'franse-boulevard-1759',
    title: 'Franse Boulevard',
    narrator: 'Petra',
    author: 'InKey',
    theme: 'straat & buurt',
    neighbourhood: 'Hart van Heemskerk',
    period: '2005',
    intro: ['Op een dag hing er ineens een grote filmcamera voor mijn raam.'],
    body: ['Ik keek naar buiten en zag allerlei mensen rondlopen. Het bleek dat ze een reclamefilmpje voor een nieuw type auto van een of ander automerk aan het opnemen waren. Alle uithangborden van de winkels waren veranderd, de originele reclameborden op de stoep waren weggehaald, er waren stoelen en tafeltjes buiten neergezet, één winkel was omgebouwd tot bloemenstal, alles om het idee te creëren dat het om een straat in Frankrijk ging. De nieuwe auto stond ergens in de straat geparkeerd en een aantal figuranten moesten enthousiast naar de auto rennen, met een hoop gejoel en lawaai en vervolgens aan die auto sjorren, er tegenaan duwen en er bovenop gaan liggen. Deze scène werd vaak, heel vaak herhaald, maar de figuranten bleven desondanks enthousiast de auto belagen.', 'Tijdens het filmen mocht je niet door de straat lopen, fietsen of rijden, tussendoor wel. Om ervoor te zorgen dat dit goed verliep liepen er een aantal mannen van een bewakingsdienst rond.', 'Jammer genoeg deden er geen bekende Nederlanders aan het filmpje mee. Misschien wordt het reclamespotje alleen in Frankrijk uitgezonden, want hier op de Nederlandse televisie heb ik het helaas nog niet voorbij zien komen.', 'Verhaal verteld op: 24-10-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1760-490-368-1.jpg', caption: 'Een grote camera hangt voor het raam; er wordt een reclamespotje opgenomen in de Van Coevenhovenstraat.')],
    relatedSlugs: ['rennende-mensen-1726', 'lost-in-donkey-jazz-2327', 'van-supermarkt-limmen-naar-turkse-buurtsuper-1635', 'een-deen-in-breedweer-1949', 'als-hond-en-kat-4339', 'radiotik-2888'],
