  MemoryStory(
    slug: 'friese-meelkoekjes-in-heemskerk-1247',
    title: 'Friese meelkoekjes in Heemskerk',
    narrator: 'Klaas van Maassen',
    author: 'Marjan Procee',
    theme: 'kastelen & landhuizen',
    neighbourhood: 'Duin tot Dorp',
    period: '1957',
    intro: ['Klaas van Maassen (1923) verhuisde met zijn gezin in 1957 van Friesland naar Heemskerk.'],
    body: ['In landbouwblad De Boerderij stond een advertentie, waarin jonkheer Daniël Gevers een bedrijfsleider zocht voor de boerderij op zijn landgoed Marquette. Ik werkte destijds op een groot fokbedrijf (van Friese paarden) in het Friese Deersum. "Nou", zei mijn vrouw, "als jij het leuk vindt, dan moet je het doen". En zo kwamen we in Heemskerk terecht.', 'De overgang van Friesland naar Heemskerk was niet al te groot, al was er wel de taalbarrière waar we mee te maken kregen. Een voorbeeld: biscuitjes heten in Friesland meelkoekjes. Mijn vrouw wilde deze bestellen bij de kruidenier die in die tijd nog met een bestelboekje aan huis kwam. Dat werd een hele discussie want die man begreep maar niet waar zij het over had.', 'We wonen hier nu 47 jaar en hebben veel vrienden en kennissen. Maar als je vraagt naar het verschil tussen Heemskerkers en Friezen, dan vinden we de Heemskerkers, hoe zal ik dat zeggen, wat meer gehaast. Friese kassameisjes nemen rustig de tijd in een supermarkt om iets voor je te halen, hier is het meer ‘opschieten’.', 'Mijn zoon, die bij de verhuizing in 1957 nog maar heel klein was, vond Heemskerk maar niks. "Ik blijf hier niet wonen", zei hij. En hij heeft woord gehouden, hij woont nu weer in Friesland.', 'Verhaal verteld op: 01-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1248-490-500-1.jpg', caption: 'De heer van Maassen met prijsstier van Marquette.')],
    relatedSlugs: ['verslaving-4346', 'emigreren-of-werken-op-kasteelhoeve-2243', 'thuis-onder-de-toren-van-de-lau-1472', 'een-grensgeval-1868', 'van-marquette-bos-naar-hoogoven-5-1280', 'hard-house-in-cafe-nijman-1854'],
