  MemoryStory(
    slug: 'geheugen-van-heemskerk-gelanceerd-1510',
    title: 'Geheugen van Heemskerk gelanceerd',
    narrator: '',
    author: 'Erwin Smit',
    theme: 'straat & buurt',
    neighbourhood: '.',
    period: '',
    intro: ['Op vrijdag 16 september 2005 om 12.00 uur is het Geheugen van Heemskerk officieel gelanceerd.'],
    body: ['Na 9 maanden voorbereiding is het zover. Heemskerk heeft zijn eigen geheugensite. Burgemeester Schneiders voltrekt de lancering op het Burgemeester Nielenplein in Heemskerk, wat voor één keer is omgetoverd in een Geheugen van Heemskerkplein. Via een scherm is het startschot goed te volgen voor de talloze nieuwsgierigen en de diverse Heemskerkse Verhalenverzamelaars. Zij zijn herkenbaar aan hun gele shirts, waarop het logo van het Geheugen van Heemskerk prijkt.', 'Het is even zoeken, maar ook het verhaal van de burgemeester is inmiddels te vinden op de site.', 'Er zijn al verschillende verhalen te bezoeken. Deze zijn de afgelopen periode allemaal opgehaald en ingevoerd door de eerste groep Verhalenverzamelaars. Gedurende de middag worden er nieuwe verhalen opgehaald op de Verhalenstoel. Bewoners vertellen daarop aan andere bewoners hun verhaal van Heemskerk.', 'Kortom, het Geheugen van Heemskerk is begonnen!'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1551-490-368-1.jpg', caption: 'Burgemeester Schneiders lanceert de website')],
    relatedSlugs: [],
  ),
  MemoryStory(
    slug: 'gescheurde-broek-1813',
    title: 'Gescheurde broek',
    narrator: 'Aad Welboren',
    author: 'Kees van Duivenvoorde',
    theme: 'duin & strand',
    neighbourhood: 'Duin tot Dorp',
    period: '1940 - 1947',
    intro: ['Zoals elke duinkat ging ook Aad Welboren wel eens stropen. Dat liep niet altijd goed af.'],
    body: ['Aad Welboren, geboren op de Maerten van Heemskerckstraat, verhuisde al spoedig naar de Voorweg, Heemskerkerduin. Voor, tijdens en na de oorlog werd er flink gestroopt in de duinen, die liepen tot aan de achterdeur van zijn woning. Het was natuurlijk zaak om uit handen van de jachtopziener Benning te blijven. Stropen was al verboden maar voor degenen die grond huurden van de familie Boreel, de eigenaren van die duinen, kon het verstrekkende gevolgen hebben. In het huurcontract stond uitdrukkelijk vermeld dat plaatsen van strikken en klemmen(sprenkels) verboden was op straffe van beëindiging van huur.', 'Als Aad \'s avonds met zijn broer thuis kwam moesten natuurlijk de strikken en klemmen nog nagezien worden. Om uit te vinden of de jachtopziener niet ergens liep werd goed gekeken en geluisterd. Door de verlichting van de Hoogovens kon je vlak over de grond de jachtopziener of andere stropers ontwaren.', 'De duinen waren in de oorlogsjaren een mooie schuilplaats voor de jonge mannen. Als er gevaar voor razzia dreigde, vluchtten zij het duin in. Dit was niet zonder gevaar want het kon zijn dat er ook mijnen verborgen lagen. Een buurjongen trapte daar ooit op en verloor een been.', 'Na de oorlog ging Aad \'s avonds nog even met een geweer de duinen in. De munitie was niet helemaal je dat en het geweer bleek niet juist geladen. Aads\' broer zag tegen de achtergrond van de Hoogovens wat wild lopen en schoot. Een enorme knal was het gevolg. De broer werd achteruit geworpen en struikelde over het daar aanwezige prikkeldraad. Gigantische scheur in de broek. Bij thuiskomst bleek hij de zondagse broek van Aad aan te hebben.', 'Verhaal verteld op: 29-11-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1814-490-367-1.jpg', caption: 'De duinen liepen tot aan de achterdeur van de woning van Aad Welboren')],
    relatedSlugs: ['verslaving-4346', 'slapen-tussen-kippengaas-1992', 'hondje-2641', 'de-zondagen-uit-mijn-jeugd-1417', 'van-marquette-bos-naar-hoogoven-5-1280', 'boete-op-zee-4580'],
  ),
  MemoryStory(
    slug: 'gillende-sirenes-2829',
    title: 'Gillende Sirenes',
    narrator: 'Sjoerd Zonneveld',
    author: 'Kees van Duivenvoorde',
    theme: 'vrijwilligerswerk',
    neighbourhood: 'Hart van Heemskerk',
    period: '2006',
    intro: ['Jeugdbrandweer leerzaam en een mooi beroep voor de toekomst'],
    body: ['Tijdens de buurtmiddag in de wijk Boven de Baandert kwam plots een brandweerauto met loeiende sirenes aansnellen. Deuren vlogen open en er kwamen hele jeugdige brandweerlieden uitspringen. Slangen werden uitgerold en geroutineerd werd een pijp gemonteerd op een brandkraan. Even later spoot een straal water richting opgestelde pionnen. We maakten kennis met Sjoerd Zonneveld. Hij woont op Heemskerkerduin. Sinds bijna twee jaar is hij lid van de Heemskerkse jeugdbrandweer. Via een neefje is hij bij de brandweer gekomen. Professioneel bediende hij de portofoon waarmee hij in verbinding staat met de wagen en de commandant. Sjoerd ziet het wel zitten om beroepsbrandweer te worden. Een baan op Schiphol bij de brandweer lijkt hem wel wat. De weg is nog lang. Je bent niet zomaar brandweerman.', 'In de eerste 4 maanden bij de jeugdbrandweer wordt uitsluitend aan theorie gewerkt. Echt vuur is dan nog niet in zicht maar de animo is er niet minder om. Tijdens de wekelijkse bijeenkomsten van de jonge spuitgasten waar zowel jongens als meisjes vertegenwoordigd zijn, wordt eerst een uur theorie gegeven en daarna pas in de praktijk geoefend. Zo hebben ze al eerder een keer geoefend bij een paardenstal, waar eerst het paard uit de stal gered moest worden voordat ze het vuur konden bestrijden.', 'Bij de kerstboomverbranding zijn de jonge spuitgasten ook altijd aanwezig. Er zijn ook wedstrijden voor de ervaren jeugdbrandweerkorpsen in Noord-Holland. Vanaf 12 jaar kun je je aanmelden bij de jeugdbrandweer. Op de website www.JeugdbrandweerHeemskerk zie je alle informatie over de jeugdbrandweer. Heel leuk en leerzaam. Jongens en meisjes kunnen zich aanmelden door een briefje te sturen naar de jeugdbrandweer van Heemskerk.', 'De wens van Sjoerd is om via de basisopleiding en dan nog vele cursussen als volwaardig brandweerman aan de slag te kunnen gaan.', 'Verhaal verteld op: 23-09-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2830-490-364-1.jpg', caption: 'Sjoer samen met collega spuitgast')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'landgoed-6201', 'het-witte-huisje-5783', 'de-buurtbus-een-heemskerks-sprookje-4205', 'de-aardbeien-opera-3237', 'graanteelt-2234'],
