  MemoryStory(
    slug: 'het-bokkewijfie-1843',
    title: 'Het Bokkewijfie',
    narrator: 'C Vonk-Baltus',
    author: 'Loes Sprengers',
    theme: 'bekende personen',
    neighbourhood: 'Van Acker tot Burcht',
    period: '1939 - 1963',
    intro: ['De weekmarkt, te vinden aan de Maerelaan', 'waar al jarenlang kooplui in hun kramen staan.', 'Daar is het gezellig om te lopen', 'een praatje te maken of iets te kopen.', 'En zoals het in menig stad of dorp is', 'heeft ook de Heemskerkse markt een geschiedenis.'],
    body: ['Er zijn al weer een aantal jaren verstreken', 'toen werd gekeken', 'naar twee aparte figuren', 'die in de late middaguren', 'de markt bezochten en door iedereen werden herkend', 'men was aan deze mensen wel gewend.', '‘In Castricum woont hij toch’, zeiden zij', 'Élke week komt hij voorbij’.', 'Zijn lang grijs haar in een paardestaart gebonden', 'aan zijn broekriem hing een enorme sleutelbos,', 'wat mensen daarvan vonden', 'was hem om ‘t even, hij liet toch niets los.', 'Nee ,...dan had je daar het bokkewijfie', 'zij zocht visafval, aangestoken appels en andijvie,', 'laadde dat op haar brakkige fiets', 'en zo had zij voor niets', 'een tijdje eten voor de geiten, kippen en de kat', 'waar zij voor zorgde, voor ieder dier wat', 'in haar bij elkaar bevolkte huis/ boerderij,', 'er hoorden ook nog konijnen bij.', 'Met haar broer woonde zij aan de oude Jan van Kuikweg', 'in een bouwvallig huisje achter een heg', 'een vreemde voor velen', 'en kon het omgaan met anderen niet delen.', 'En wat wordt dan jouw toebedeelde lot?', 'Wie zich anders gedraagt wordt uitgescholden en bespot.', 'Verhaal verteld op: 03-12-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1845-490-361-1.jpg', caption: 'Greetje en George Kaspers, beter bekend als \'t Bokkewijfie\' en \'malle Frits\' (bron: Historische Kring Heemskerk)')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'de-smederij-van-piet-van-t-hoekie-2745', 'muziek-op-het-kerkplein-2298', 'merkwaardig-4870', 'radiotik-2888', 'het-doek-is-gevallen-4280'],
