  MemoryStory(
    slug: 'het-doek-is-gevallen-4280',
    title: 'Het doek is gevallen',
    narrator: '',
    author: 'Loes Sprengers',
    theme: 'verdwenen plekken',
    neighbourhood: 'Hart van Heemskerk',
    period: '1947 - 1969',
    intro: ['Kort na de oorlog (1940/’45), fietsten de gebroeders Engel en Bertus Henneman met hun vrouwen na een filmvoorstelling in het Castricumse Corsotheater terug naar Heemskerk.'],
    body: ['Tijdens deze rit, wakkerde een klein vlammetje bij hen aan, vervolgens sloeg de vlam in de pan tot een verhit plan.', 'In Heemskerk vonden zij, móet een bioscoop komen!', 'De gebroeders gingen aan de slag, wisten Burgemeester, gemeenteraad en Pastoor te overtuigen, lokatie op te sporen. Het Patronaatsgebouw aan de Deutzstraat was toch van de kerk?', 'Zij overwonnen obstakels, kregen de nodige vergunningen en geloof het of niet; de eerste bioscoopfilm werd vertoond.', 'Maar zonder een operateur, geen filmvoorstelling en wie wilde daar hun vrije tijd aan geven, een verplichte cursus volgen met alle voorschriften, bepalingen en praktijkuren ?', 'Engel’s slimme oog viel op de jongens Sprengers. Kreeg Joop zover om de filmapparatuur te bedienen, een cursus te volgen en af te ronden met het operateursdiploma. Kort daarna volgde broer Jan en Jan heeft het gepresteerd om 50 jaar lang, filmvoorstellingen, meestal in de weekeinden in vaak bloedhete cabines te vertonen.', 'De bioscoop, “Het Marquette-Theater” bleek een schot in de roos voor de Heemskerkers. Drukbezochte matineevoorstellingen op zondagmiddag hielden bengels van de straat.', 'De gemeenteontvanger in vol ornaat, gaf de bioscoopkaartjes persoonlijk af aan de gebroeders Henneman voor aanvang van de voorstelling i.v.m. de opgelegde vermakelijkheidsbelasting.', 'Jan Beentjes, de kalmte in persoon, fungeerde als uitsmijter en Stien Kloes verkocht snoep.', 'Helaas in 1969 vond de sloop plaats van het nog geen 50 jaar oude Patronaatsgebouw/ Marquette-Theater. De bioscoop, reeds in handen van Fam. Kluft verhuisde naar een nieuw onderkomen aan de Ruysdaelstraat en kreeg de naam “Cinema Marquette”.', 'Gewijzigde dorpsplanning, aanpassing van bouwvoorwaarden, einde “Cinema Marquette.” Voor het Heemskerkse bioscooptheater viel het doek.', 'Verhaal verteld op: 29-10-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4282-490-367-1.jpg', caption: 'Het gebouw waarin de gebroeders Henneman de Heemskerkse bioscoop begonnen.')],
    relatedSlugs: ['hard-house-in-cafe-nijman-1854', 'lost-in-donkey-jazz-2327', 'de-smederij-van-piet-van-t-hoekie-2745', 'merkwaardig-4870', 'een-leven-lang-op-de-planken-5388', 'alarm-zonder-sirenes-1747'],
  ),
  MemoryStory(
    slug: 'het-einde-van-een-begin-1718',
    title: 'Het einde van een begin',
    narrator: '',
    author: 'Wendy Bosch',
    theme: 'liefde & huwelijk',
    neighbourhood: 'Hart van Heemskerk',
    period: '1993',
    intro: ['Hier begon het; mijn nieuwe leven in Heemskerk. Maar liefst tweehonderd kilometer vandaan bij alles wat me vertrouwd was. En dat allemaal voor de liefde...'],
    body: ['Hoe lang kenden we elkaar nou eigenlijk? Nog niet eens een jaar. Toch heb ik geen seconde getwijfeld toen HIJ vroeg of ik bij \'m wilde komen wonen. Ik, het meisje dat al heimwee had wanneer ze bij de buren sliep. Tot ieders verbazing besloot dat zelfde meisje om aan de andere kant van Nederland te gaan samenwonen met haar grote liefde.', 'En hier begon het dus, in de Chopinstraat op nummer 8. Inmiddels staan er hekken rondom de flat en woont er niemand meer. Over niet al te lange tijd wordt het gebouw met de grond gelijk gemaakt. De buurt krijgt een grondige make-over. De flat moet wijken voor nieuwbouw.', 'In 1998 trok ik zonder moeite de deur van de flat definitief achter me dicht. De flat werd verruild voor een eengezinswoning. Nu in 2005 moet ik toch wel even slikken bij de gedachte dat de flat waar het voor ons allemaal begon over niet al te lange tijd niet meer zal bestaan...', 'Verhaal verteld op: 02-11-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1719-490-368-1.jpg', caption: 'De flat aan de Chopinstraat, vlak voor de sloop.')],
    relatedSlugs: ['eerste-deuntje-3046', 'het-witte-huisje-5783', 'snotneus-op-klompen-3154', 'emigreren-of-werken-op-kasteelhoeve-2243', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472'],
