  MemoryStory(
    slug: 'het-gat-van-heemskerk-3558',
    title: 'Het Gat van Heemskerk',
    narrator: 'Peter Vendel',
    author: 'Peter Vendel',
    theme: 'straat & buurt',
    neighbourhood: 'Hart van Heemskerk',
    period: '1975',
    intro: ['Het moet ongeveer 1975 zijn geweest en het was op de kruising van de Carel van Manderstraat en de Ruysdaelstraat. Er was een gat in de weg en niemand begreep er iets van.'],
    body: ['Wekenlang was de kruising afgesloten. Er werd zelfs een brandweerwagen neergezet en de politie stuurde iedereen weg. Er kwam op een dag ook een cameraploeg van het NOS Journaal. Ik heb het zelf ook op Het Journaal gezien. Er ontstond veel commotie. Er bleek een lantaarnpaal onder stroom te staan en uit de grond kwam rook. Het was voor mij, als jongetje van 12 jaar, interessant. Omdat de digitale wereld nog moest worden uitgevonden, was dit voor ons heel spannend. De oorzaak kon niemand vinden. De bewuste lantaarnpaal werd later op een andere plek gezet. Maar daar begon het euvel opnieuw. Uiteindelijk het bleek in de legering te zitten.', 'Verhaal verteld op: 15-05-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3560-490-654-1.jpg', caption: 'Peter Vendel wijst de plek aan waar het mysterieuze gat destijds zat. Bij de vijver aan de Ruysdaelstraat.')],
    relatedSlugs: ['eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'merkwaardig-4870', 'droom-spat-uiteen-4305', 'varkenslapjes-in-de-sneeuw-3352', 'rennende-mensen-1726'],
  ),
  MemoryStory(
    slug: 'kruidenierswinkeltje-4916',
    title: 'Kruidenierswinkeltje',
    narrator: 'Piet Castricum',
    author: 'Jeanne Castricum',
    theme: 'straat & buurt',
    neighbourhood: 'Duin tot Dorp',
    period: '1942 - 1943',
    intro: ['Mijn vader werd door de buren ‘Ome Jan van het kruidenierswinkeltje’ genoemd. Hij slachtte in de oorlog koeien en varkens bij tuinders op de akker. Zijn gezin telde zeven zonen. Daar moesten vele mondjes worden gevuld Hij werd echter verraden.'],
    body: ['Op een dag in 1942 kwamen er twee controleurs en onderzochten ons winkeltje. Maar alles was op, er viel niet veel te zoeken. De voorraad werd steeds kleiner en door gebrek aan levensmiddelen niet meer bijgevuld. Achter het luik op zolder vonden ze wel een emmer met varkenskarbonade onder het vet. En onder het bed lagen twee juten zakjes bruine bonen verborgen voor eigen gebruik. Die namen ze mee. Mijn oudste broer liep achter de mannen aan, pikte een gat in de zak en hield er een schaaltje onder zodat hij wat bonen opving. Vader werd meegenomen en kwam in strafkamp Veenhuizen terecht. Hij werd er een maand opgesloten en met stokslagen afgetuigd. Mijn moeder bleef in onzekerheid achter met een schaaltje bruine bonen, zeven zonen en dochtertje. Toen vader plotseling toch thuis kwam, zwart van magerte, was de blijdschap groot .', 'Verhaal verteld op: 08-03-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4917-490-323-1.jpg', caption: 'Het kruidenierswinkeltje werd in 1952 overgenomen door de familie Nijman.')],
    relatedSlugs: ['slapen-tussen-kippengaas-1992', 'eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'hondje-2641', 'thuis-onder-de-toren-van-de-lau-1472'],
  ),
  MemoryStory(
    slug: 'het-offerblok-2653',
    title: 'Het Offerblok',
    narrator: 'Nico Sinnige',
    author: 'Kees van Duivenvoorde',
    theme: 'verdwenen plekken',
    neighbourhood: 'Duin tot Dorp',
    period: '1926',
    intro: ['Jongens vinden geldkist in verbrand cafe'],
    body: ['Offerblok', 'De neven Nico en Johan Sinnige moesten dagelijks lopend vanaf de Rijksstraatweg naar kerk en school. Eerst langs bakker Schuijt om de baktrommel af te leveren. De bakker bakte het zelfgemaakte brood. Op een morgen was het tegenover de bakkerij een drukte van belang. Mensen liepen met slangen te slepen en de brandweer was aan het nablussen. Café Halfweg was die nacht volledig afgebrand. De jongens keken hun ogen uit en waren niet meer op tijd in de kerk. Tijdens de les waren zij steeds bezig met de brand. Na schooltijd moesten zij het brood ophalen en gingen weer even bij het afgebrande café kijken.', 'De volgende dag was het woensdag en waren de kinderen ‘s-middags vrij. Zij gingen weer kijken naar de rampplaats. Het biljart stond er nog, ook de zwartgeblakerde toog. Veel gebroken glaswerk op de grond. Johan zag iets liggen en raapte het op. Het was een kistje met een deksel met de tekst “Armen”. Het offerblok. Dit stond altijd op de toog. Door de gleuf konden de klanten wat wisselgeld doen. Johan schudde er mee en hoorde geld rammelen. Zij wisten het slot te forceren en namen de inhoud mee naar huis. Wat voelden zij zich rijk. De volgende ochtend gingen zij voor schooltijd naar de snoepwinkel van Teun Winter en zochten toverballen, nogablokken en snoep uit. Na de mis werd op het schoolplein flink gesnoept. In de middagpauze en na schooltijd ook volop snoep. Het eten was die avond niet erg in trek. Erger, de jongens waren misselijk.', 'De volgende dag was geld en snoep op. Het geweten van Nico begon te knagen. Het was toch geld voor de “Armen” Hij sprak erover met Johan. Die had geen gewetenswroeging. Hij had heerlijk gesnoept. Bij Nico bleef het knagen. Hij ging naar moeder en biechtte alles op.', 'Verhaal verteld op: 15-06-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2664-490-289-1.jpg', caption: 'Foto gemaakt ter hoogte van afgebrand cafe Halfweg')],
    relatedSlugs: ['eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'merkwaardig-4870', 'droom-spat-uiteen-4305', 'thuis-onder-de-toren-van-de-lau-1472', 'varkenslapjes-in-de-sneeuw-3352'],
  ),
  MemoryStory(
    slug: 'het-uitzicht-1331',
    title: 'Het uitzicht',
    narrator: 'Rie Roozendaal',
    author: 'Rie Roozendaal',
    theme: 'straat & buurt',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '1998 - 2005',
    intro: ['Rie Roozendaal (1924) woont vanaf 1998 in Huize de Nouweland aan het Europaplein. Vanuit haar raam is ze getuige van alle veranderingen in de buurt.'],
    body: ['In de ruim vijf jaar dat ik aan de achterkant van Huize de Nouweland woon, is daar heel wat veranderd. Een gebouw waar ik van driehoog op uitzie, was al van een school voor kinderen in een plek voor ouderen veranderd, De Stut. Het verving voor een deel het buurthuis dat daar voor die tijd een noodgebouw was. De school op de hoek van de Frankrijklaan veranderde in buurthuis De Globe en kinderopvang Kangoeroe.', 'Een grasveldje veranderde in een parkeerplaats en er werden wat bomen gerooid.', 'Daaronder was een heel grote abeel. Heel slank en blank en voor mij was het altijd het punt waar ik zag hoe de windrichting grotendeels was. Bij zuiden- en zuidoostenwind zag ik de zilverkleurige achterzijdes van de bladeren. Op de restanten van de boom groeide een paddestoel, één die heel veel aandacht trok, zo vlak op het pad. Het was een schoonheid, en ik heb er een foto van gemaakt. Bij het rondgaan van de foto kwamen we erachter waarom de boom gekapt was. Het pad dat er vlak langs loopt, werd er door beschadigd. En met al die oude mensen die er langs naar De Stut gaan was dat te gevaarlijk geworden. Jammer hoor.', 'Verhaal verteld op: 15-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1333-340-255-1.jpg', caption: 'Vanaf haar balkon kijkt Rie Roozendaal op het plein aan de Garonnestraat. Met buurthuis De Stut (links) en buurthuis De Globe (rechts).')],
    relatedSlugs: ['eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472', 'paasbest-5015', 'een-grensgeval-1868'],
  ),
  MemoryStory(
    slug: 'het-van-tunendorp-4152',
    title: 'Het Van Tunendorp',
    narrator: 'Wim van Tunen',
    author: 'Loes Sprengers',
    theme: 'straat & buurt',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '',
    intro: ['Aan de Communicatieweg, vlak voor de viaduct opgang van de A9 vanaf Heemskerk aan de rechterkant, daar waar tevens de toegangsweg naar de Broekpolder is gerealiseerd, ligt het VAN TUNENDORP. In dat puntje tussen de landerijen woonden en wonen de van Tunens, mijn familie.'],
    body: ['Ik ben geboren en getogen op één van de boerderijen en we waren met vijf familieleden lid van de Vrijwillige Brandweer Heemskerk. Een uniek feit deed zich voor in 1996, toen we met 3 van Tunens ons 25-jarig brandweerjubileum vierden. Naast de vele festiviteiten werd op de plaats waar onze roots liggen, een prachtig bord onthuld. In het bijzijn van burgemeester Hoobroeckx, brandweercommandant Schinning en de pers waren Jaap, Rob en ik zeer ingenomen met deze ludieke actie. Op zekere dag fietste ik voorbij mijn dorp en zag tot mijn ontsteltenis het vertrouwde bord niet meer. Gestolen? Navraag leverde niets op. Ik schreef naar de krant en hoopte dat de dader tot inkeer zou komen. Maar voor iets gepubliceerd zou worden, was het raadsel al opgelost. De krant wilde opheldering hierover en trof Arie van Tunen die verklaarde dat zijn dochter het bord uit voorzorg had weggehaald uit angst voor beschadiging door werkzaamheden in de Broekpolder. Zodra deze voorbij zijn keert het VAN TUNENDORP-bord terug. Ik kan gerust zijn: "mijn dorp” bestaat nog steeds!'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4154-490-396-1.jpg', caption: 'Op de foto Rob en Wim van Tunen, (oud) burgemeester Hoobroeckx, Jaap van Tunen en brandweercommandant Schinning')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'thuis-onder-de-toren-van-de-lau-1472', 'eerste-deuntje-3046', 'verslaving-4346', 'een-grensgeval-1868', 'rennende-mensen-1726'],
  ),
  MemoryStory(
    slug: 'het-witte-huisje-5783',
    title: 'Het witte huisje',
    narrator: '',
    author: 'Jeanne Castricum',
    theme: 'straat & buurt',
    neighbourhood: 'Hart van Heemskerk',
    period: '1970 - 2008',
    intro: ['Midden in het dorp tussen de huizen aan de vijver staat nog een oud huisje. Joep en Sofie hebben met hart en ziel gewerkt om hier iets te behouden van hoe het vroeger was.'],
    body: ['Hoe komen Joep uit Terschelling en Sofie uit Groningen aan dit plekje? Joep kwam in 1970 aan de Professor ten Doesschatestraat wonen. Hij zocht werk aan wal, want op de grote vaart ben je maanden van huis en elke keer afscheid nemen van vrouw en kind viel niet mee. Er kwame steeds veel tranen en zijn kind groeide op en miste een vader. Daarom besloot hij in IJmuiden te gaan werken. Als leraar kwam hij indertijd bij de zeevaartschool terecht.', 'Sofie hoorde op de tennisvereniging dat een oude man het huisje wilde verkopen. Sofie liet er geen gras over groeien. Ze ging er snel op af en zo werden ze eigenaars. Hoe het vroeger was is nog in de woning terug te vinden: een smalle trap naar boven, beneden de deurtjes van de bedstee, het oude balkenplafon in de kamer, alles lieten zij in oude stijl. In de tuin rondom het huisje bloeit alles weelderig en zie je nog een welput. Het bijzondere huis van Joep en Sofie is een rustpunt in het hart van het dorp.', 'Verhaal verteld op: 08-10-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.5806-490-363-1.jpg', caption: 'het witte huisje')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'verslaving-4346', 'emigreren-of-werken-op-kasteelhoeve-2243', 'landgoed-6201', 'de-muur-is-rond-1692', 'de-beste-plek-van-de-wereld-2039'],
  ),
  MemoryStory(
    slug: 'het-zwarte-kistje-van-de-freule-5002',
    title: 'Het Zwarte Kistje van de Freule',
    narrator: 'Nel Stammes',
    author: 'Loes Sprengers',
    theme: 'bekende personen',
    neighbourhood: 'Duin tot Dorp',
    period: '1945 - 1970',
    intro: ['De Freule Gevers van Kasteel Marquette wist dat ik Duitse herdershonden fokte. Ze was weleens komen kijken. Bij het vertrek van de familie Gevers uit Heemskerk gaf zij mij een oud zwart kistje cadeau. Het was gevoerd met behangpapier er er zaten penningen in uit 1921 van jachtspaniels en herdershonden.'],
    body: ['“Dit is iets voor jou”, zei ze, “jij had toch altijd honden?” Inderdaad heb ik in de zeventiger jaren herdershonden gefokt. Boer Wentink aan de Oosterweg kende mensen die een Duitse herder kwijt wilden. Wentink vroeg of wij haar wilde hebben. Na enige aarzeling namen wij de schuwe hond. Hij bleek een stamboom te hebben. Het was zo’n lief dier en daarmee ben ik gaan fokken. Ik kreeg wel controle en de controleur vroeg me verbaasd of ik kynologie had gestudeerd, omdat ik zoveel wíst. Ik dacht gewoon logisch na: als iets hard groeit is er iets extra’s nodig.', 'Gewoonlijk omvatte een nestje zes tot acht hondjes. Maar één keer waren het er twaalf. Te veel voor moederhond. Vaak zitten er dan zwakkelingen bij, maar dit waren mooie gezonde hondjes, zo schattig! Toch moesten er een paar weg. Toen de dierenarts de volgende dag kwam lagen de hondjes beurtelings lekker warm onder een kuikenlamp en bij de moeder. Dat had ik zo bedacht. Kuikens overleefden het toch ook! Elke dag haalden we een emmer melk bij Wentink’s boerderij. Kregen ze bijvoeding, een bordje brinta met extra’s. De krant kwam een foto maken want dit was voor tóen, uniek. Met mooi weer liet ik de puppies buiten, had dan letterlijk mijn handen vol! Een leuke tijd!', 'Door mijn interesse werd ik erkend en zo kregen we in 1969 een driesterren kennel aan de Marquettelaan genaamd De Zwanemaer.', 'Verhaal verteld op: 11-03-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.5003-490-368-1.jpg', caption: 'Het zwarte kistje met penningen van jachtspaniels en herdershonden uit 1921. Nel Stammes kreeg het van mevrouw Gevers van Kasteel Marquette tijdens de afscheidsmiddag.')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'snotneus-op-klompen-3154', 'emigreren-of-werken-op-kasteelhoeve-2243', 'het-witte-huisje-5783', 'de-smederij-van-piet-van-t-hoekie-2745', 'ik-baalde-als-een-stekker-2048'],
  ),
  MemoryStory(
    slug: 'hippie-met-koekkruimels-1714',
    title: 'Hippie met koekkruimels',
    narrator: 'Irma Elsheikh-Dekker',
    author: 'Marjan Procee',
    theme: 'school',
    neighbourhood: 'Hart van Heemskerk',
    period: '1975 - 2005',
    intro: ['Irma Elsheikh-Dekker (1963) was ver na het flowerpowertijdperk hippie in Heemskerk. Ze vertrok voor werk maar kwam in 2000 weer in haar geboortedorp wonen.'],
    body: ['In Heemskerk was geen havo, dus ging ik naar het Bonhoeffer in Castricum. Iedere vrijdagmiddag zat ik na schooltijd met een groepje vrienden in de kuil op het Nielenplein. De kuil is nu dichtgegooid, maar destijds was er een trapje naar beneden gemaakt en kon je er zitten.', 'Op de vrijdagmarkt kochten we eerst voor een kwartje een zak koekkruimels bij de man van de stroopwafels en vervolgens trokken we naar de kuil. Er zaten altijd twee groepen, de hippies aan de ene kant en de punkers aan de andere kant. Ik hoorde bij de hippies, hoewel het flowerpowertijdperk al lang voorbij was. Een aantal vrienden hadden een bandje en soms speelden ze gitaar maar meestal waren we gewoon aan het kletsen en aan het kijken. Af en toe was er ruzie met de punkers. Sommige punkers waren nogal agressief. Dan was het vechten en elkaar met koekkruimels bekogelen.', 'Met een paar mensen uit deze vriendengroep heb ik nog steeds contact. Die vriendschappen zijn onder meer de reden geweest dat ik in 2000 weer in Heemskerk ben komen wonen. Mijn beste vriendin van de middelbare school woont hier en ook mijn ouders en broer met zijn gezin. Daarnaast ben ik hier weer komen wonen omdat mijn twee dochtertjes er veilig buiten kunnen spelen. In Amsterdam, waar we woonden, kon dat niet. Alleen mijn Sudanese man had er in het begin een beetje moeite mee om hier te wonen. Hij moest al in Amsterdam aan de Nederlandse cultuur wennen, en dan in het dorp Heemskerk nog meer. Maar de Heemskerkse kermis, waar ik zelf niet zo vaak heen ga, vindt hij wel erg leuk.', 'Verhaal verteld op: 28-09-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1715-425-318-1.jpg', caption: 'Er zijn nog steeds koekkruimels te koop op de vrijdagmarkt')],
    relatedSlugs: ['dodenherdenking-5263', 'paasbest-5015', 'nonnenfrustratie-1658', 'een-leven-lang-op-de-planken-5388', 'zitkuil-tevens-vijver-1326', 's-lands-wijs-s-lands-eer-4347'],
  ),
  MemoryStory(
    slug: 'hkh-in-de-top-4778',
    title: 'HKH in de top!',
    narrator: '',
    author: 'Leny Gigengack',
    theme: 'vrijwilligerswerk',
    neighbourhood: 'Hart van Heemskerk',
    period: '',
    intro: ['De Historische Kring Heemskerk is met ruim 2000 leden één van de grootste in zijn soort in Noord Holland. Dit was bij de start in december 1988 niet de verwachting van de initiatiefnemers. Die dachten aan een vijtigtal leden. Het gestencilde clubblad dat zij voor ogen hadden, is nooit verschenen'],
    body: ['Voorzitter Niek Linger en redacteur van De Heemskring Piet Gooijer delen hun liefde voor geschiedenis, in dit geval voor die van Heemskerk. Piet is al van het begin betrokken bij de Kring en vooral bij De Heemskring. Dit is het tijdschrift dat tweemaal per jaar verschijnt. De onderwerpen die daarin voorkomen, ontstaan vaak spontaan uit een terloopse opmerking. Piet geeft als voorbeeld dat iemand het woord \\\'bunkers\\\' laat vallen. Dan blijkt diegene een schat aan gegevens en verhalen daarbij te hebben. Het kost meestal heel veel tijd om van de hoeveelheid materiaal een goed artikel te maken. De leesbaarheid staat voorop, want het blad wordt gemaakt voor de lezers en niet voor de schrijvers! In elk artikel wordt gestreefd naar 40 procent foto’s en 60 procent tekst. Kwaliteit bewaken is heel belangrijk: niet alles wat binnenkomt is te gebruiken en dat is voor sommige mensen een teleurstelling.', 'In de begintijd kreeg ieder bestuurslid 10 Heemskringen mee om daarmee nieuwe leden te werven en dat lukte wonderwel. Zo waren er al gauw 1500 leden en dat zijn er nu al weer jaren ruim 2000!', 'Incidenteel wordt met de bibliotheek samen gewerkt.', 'Op naar het 25-jarig bestaan met activiteiten waarover we de komende tijd zeker meer zullen horen.', 'Verhaal verteld op: 06-02-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4785-271-177-1.jpg', caption: 'Een stukje A. Verherentstraat, dat naar het Hoge Werfie leidde (nu Ingen Houszstraat). De foto is genomen op de hoek van de Kerklaan/ A. Verherentstraat')],
    relatedSlugs: ['het-witte-huisje-5783', 'snotneus-op-klompen-3154', 'landgoed-6201', 'de-muur-is-rond-1692', 'de-beste-plek-van-de-wereld-2039', 'graanteelt-2234'],
  ),
  MemoryStory(
    slug: 'hoe-de-mariaschool-de-otterkolken-werd-2672',
    title: 'Hoe de Mariaschool de Otterkolken werd',
    narrator: '',
    author: 'Henritte Dekkers',
    theme: 'school',
    neighbourhood: 'Boven de Baandert',
    period: '1970',
    intro: ['Toen in januari 1970 basisschool De Otterkolken startte, werd de oorspronkelijke zusterschool voor meisjes, de Mariaschool, opgeheven. De Josephschool bleef in het centrum en hield zijn naam.'],
    body: ['Het schoolbestuur vroeg of Frans Wiegmans, het hoofd van de Mariaschool, eens over een nieuwe naam wilde nadenken. Zij stelden voor "Mgr. Bekkersschool". Hij voelde er niet echt iets voor en ging eens met het team praten. \'Kapelaan Huiboom\', die in de oorlog veel voor Heemskerk betekend had, werd het ook niet. Zo kwamen er meer tips. De ruimtevaart nam in die jaren een grote vlucht en al grapjesmakend stelde meneer Wiegmans voor de school \'De eerste trap\' te noemen, want het was voor de leerlingen de eerste trap naar het vervolgonderwijs! Er moet in het schoolarchief nog een lijst zijn met al die naamideeën. Meneer Wiegmans had als hobby archeologie en hij dacht: "Hoe zou het hier vroeger geheten hebben?" Hij stapte naar de Gemeente, naar de heer van Wijk. Die was natuurlijk in het bezit van de oude kaarten. Aan de rand van het landje dat in de 16e eeuw \'Otterkolken\' heette, werd de nieuwe school gebouwd. Toen was de keuze snel gemaakt. Hoewel het schoolbestuur aanvankelijk reageerde met: "Maar meneer Wiegmans, het is toch geen openbare school!", bleken de bezwaren niet onoverkomelijk te zijn. Bovendien werd er een trend gezet. Veel meer scholen en straten hebben toen namen gekregen die al lang geleden in de omgeving voorkwamen.'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2606-490-342-1.jpg', caption: 'De Otterkolken voorjaar 2006 - gemaakt door Ally Jansen')],
    relatedSlugs: ['paasbest-5015', 'eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472'],
  ),
  MemoryStory(
    slug: 'honderdtwaalf-uur-op-een-paal-zitten-3183',
    title: 'Honderdtwaalf uur op een paal zitten!',
    narrator: 'Peter van Duivenvoorde',
    author: 'Loes Sprengers',
    theme: 'feesten & evenementen',
    neighbourhood: 'Hart van Heemskerk',
    period: '1976',
    intro: ['Vijf deelnemers uit Heemskerk braken een Europees record. Het was zondag 5 september 1976 toen zij om 12 uur van hun paal afstapten. Een zitplank van veertig bij veertig centimeter, op twee meter hoogte en met een steunlat voor de voeten. Het was géén competitie, maar de tijden werden wel genoteerd.'],
    body: ['Ik zat op paal twee. Waarom gaf ik mij op? Och! Wel eens gekeken. Op een gegeven moment sprak ik mijn neef, die dacht dat hij langer zou zitten dan ik en ik dacht het omgekeerde. We sloten een weddenschap, gaven ons op en streden tegen elkaar.', 'Het werd een uithoudingsslag, maar ik had een goede conditie. Elke twee uur was er een sanitaire stop en beweging. Gelukkig kon ik goed slapen op die paal. In elkaar gezeten haalde ik wel zes uur. Kermis vieren is voor mij te gek maar dit was een grandioos gevoel. Kermis ànders! Veel mensen kwamen langs. Kijken wie er nog zat! Sommigen aangeschoten uit de kroeg, anderen die s’morgens om vijf uur naar de Hoogovens gingen. Aanmoedigingen van familieleden die eten brachten. Prima weer. Er bleek zelfs een parasol tegen de zon nodig te zijn.', 'We maakten zelf het nieuws. Mijn paalbuurman Jan gaf het vrijdag’s op. Ging zich opknappen en kwam terug. Hij zat op mijn strobaal toen bezoekers langskwamen en vroegen wat er met Jan was gebeurd? Jan, onherkenbaar geworden, zei: “Ja, die is vannacht met zijn kop op die strobalen gevallen en afgevoerd met een ziekenauto. Maar het gaat goed met hem.” Het haalde zelfs de krant!', '‘s Nachts was de politie op zoek naar kroeglopers die de klokken van de dorpskerk luidden.', 'Aangeboden premies werden bijgeschreven op je scorebord. Geweldig maar niet de doelstelling. Je werd bekend, zelfs na het paalzitten vroegen ze of het goed met je ging.', 'Verhaal verteld op: 10-12-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3156-490-479-1.jpg', caption: 'Peter van Duivenvoorde zittend op paal 2 in 1976 op de open plek a.d. Mrt.v.Heemskeckstraat waar nu de winkel van Big Boss Visser is. De zaal van Cinema "Marquette"op de achtergrond.')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'het-witte-huisje-5783', 'de-smederij-van-piet-van-t-hoekie-2745'],
