  MemoryStory(
    slug: 'hondje-2641',
    title: 'Hondje',
    narrator: 'Nico Sinnige',
    author: 'Kees van Duivenvoorde',
    theme: 'verdwenen plekken',
    neighbourhood: 'Duin tot Dorp',
    period: '1943',
    intro: ['Om een revolver te krijgen stal Henkie een hond van de straat'],
    body: ['Henkie Verdonk werd in 1943 opgepakt door de politie. Hij zou en hondje hebben opgepikt van straat. Wat moest Henkie met dit hondje? Ruilen voor een revolver. Niet dat Henkie in het verzet zat maar hij had een revolver gezien bij zijn vriend Jan Sinnige. Deze Jan was fietsenmaker en had zijn werkplaats op de Rijksstraatweg. Bij Jan was een van de verhuurfietsen gestolen. Hij wilde dus zijn spullen bewaken. Hij was wel in bezit van een revolver maar dat ding werkte niet. De revolver stamde nog uit de tijd dat Jan’s vader jachtopziener was bij Baron Boelens van de Haer, eigenaar van het duingebied in Heemskerk. Henkie had de revolver gezien en was er helemaal verliefd op geworden. Hij zou dus zorgen voor een waakhond en zou dan de revolver daarvoor in ruil krijgen', 'Het was door een dame gezien dat Henkie een hondje van straat plukte en door gegeven aan veldwachter van der Werf. Zodoende werd Henkie opgepakt en deed zijn verhaal. Twee rechercheurs gingen op bezoek bij Jan Sinnige. Zij vroegen naar de revolver. Jan pakte dat ding en liet het zien. Hij had echter geen wapenvergunning. De revolver werd in beslag genomen . Of er nog munitie was? Neen, het ding werkte toch niet. De rechercheurs vertrouwden het niet en gingen over tot huiszoeking. Niet veel later een triomfkreet. Twee dozen gevonden waarop stond dat de inhoud bestond uit 25 patronen. Jan werd niet zenuwachtig. De rechercheur opende vol spanning de dozen. Het bleken lichtzekeringen dan wel stoppen van 6 en 10 Ampère te zijn. Teleurgesteld dropen de dienders af maar gaven Jan nog wel een bekeuring wegens verboden wapenbezit. Jan heeft hier echter nooit iets van gehoord', 'Verhaal verteld op: 15-06-2006'],
    figures: [],
    relatedSlugs: ['slapen-tussen-kippengaas-1992', 'eerste-deuntje-3046', 'verslaving-4346', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'rennende-mensen-1726'],
  ),
  MemoryStory(
    slug: 'ijsgekte-5974',
    title: 'IJsgekte',
    narrator: '',
    author: 'Jeanne Castricum',
    theme: 'straat & buurt',
    neighbourhood: 'Van Acker tot Burcht',
    period: '2009',
    intro: ['Het is dolle pret voor de kinderen van de Lunettenschool aan de Maarten van Heemskercktraat: geen speelkwartier op het schoolplein, wel IJSVRIJ.'],
    body: ['Jongens en meisjes en hun begeleiders binden de schaatsen aan. De vijver waar ik op uitkijk is deze middag een echt winterstafereel.', 'Een vader trekt een sleetje heen en weer en elk kind draait elke keer het rondje mee. Een stoeltje met een duwend beginnertje schuifelt haar eerste slagen op glad ijs. Het gaat met vallen en opstaan maar wel met veel plezier. Er zit heel wat talent tussen de kinderen, ze zweven over het ijs. Wat een heerlijk gezicht om iedereen te zien bewegen naar eigen kunnen op dunne of dubbele ijzers. Wat zullen ze de juf en meester vertellen de volgende dag? IJspret.', 'Verhaal verteld op: 16-01-2009'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.5975-490-276-1.jpg', caption: 'Het gaat met vallen en opstaan, maar wel met plezier.')],
    relatedSlugs: ['eerste-deuntje-3046', 'paasbest-5015', 'verslaving-4346', 'snotneus-op-klompen-3154', 'dodenherdenking-5263', 'thuis-onder-de-toren-van-de-lau-1472'],
