  MemoryStory(
    slug: 'ik-baalde-als-een-stekker-2048',
    title: 'Ik baalde als een stekker',
    narrator: '',
    author: 'Tom Sikkema',
    theme: 'bekende personen',
    neighbourhood: 'Hart van Heemskerk',
    period: '2005',
    intro: ['Dat Rafael van der Vaart ging trouwen in ons kleine Heemskerk was groot nieuws.'],
    body: ['Heemskerk was op 10 juni 2005 even de hoofdstad van Nederland. Rafael van der Vaart en Sylvie Meis gingen trouwen in ons dorp. Er was complete chaos voor de Laurentiuskerk. Vele Heemskerkers waren er bij. Ook bij Marquette was het druk.', 'In de krant stond dat de scholen vrij waren in Heemskerk. Daar klopte niets van. De Otterkolken gaf geen vrij. Ik baalde als een stekker omdat ik geen vrij kreeg. Gelukkig gingen we die dag op schoolreisje. Dus het was wel de moeite waard om naar school te gaan.', 'Mijn buurjongetje kreeg wel vrij en dat vind ik nog steeds niet eerlijk. Het was echt het huwelijk van het jaar! Het kwam overal op de televisie en de radio. Overal waren langs de oprit grote boeketten met witte rozen geplaatst. Een dag later ging ik met mijn vader nog even kijken. Een grote vuilcontainer was helemaal gevuld met strikken, linten en bloemen.', 'Verhaal verteld op: 08-12-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2049-360-240-1.jpg', caption: 'Langs de oprit stonden grote boeketten met witte rozen.')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'emigreren-of-werken-op-kasteelhoeve-2243', 'de-smederij-van-piet-van-t-hoekie-2745', 'muziek-op-het-kerkplein-2298', 'radiotik-2888', 'een-hoed-met-een-veertje-1469'],
