  MemoryStory(
    slug: 'je-ziet-ze-genieten-op-de-soos-1422',
    title: 'Je ziet ze genieten op de soos',
    narrator: '',
    author: 'Wendy Bosch',
    theme: 'vrijwilligerswerk',
    neighbourhood: 'Hart van Heemskerk',
    period: '2005',
    intro: ['Buurtcentrum het Spectrum, vrijdagavond 20.00 uur. De eerste busjes arriveren. Vrijwilligers Ineke, Hennie en Huub staan klaar om hun gasten van die avond te ontvangen.'],
    body: ['Al 25 jaar biedt de vrijdagavondsoos in Heemskerk een gezellige avond voor mensen uit diverse woongemeenschappen en zorginstellingen in de regio.', 'Zo’n acht jaar geleden reageerde Ineke op een advertentie waarin vrijwilligers gevraagd werden. Met enige reserve – gezien de toch wel speciale doelgroep – meldde zij zich aan. Inmiddels kijkt ze lachend terug op die eerste aarzeling en kan ze zich de vrijdagavond zonder soos niet meer voorstellen. “Het is m’n ziel en zaligheid! De genegenheid voor de bezoekers straalt van haar af.', 'Vrijwilligers Huub en Hennie waren op zoek naar een manier om meer te betekenen voor de medemens. Via Ineke kwamen ze terecht bij de soos. “Het was precies wat we wilden”, aldus Huub. “Noem het maar een overtuiging dat het leven niet alleen bestaat uit eigen belang”. Samen met zijn vrouw Hennie draaien zij inmiddels ook al weer een aardige tijd mee in het hechte team van vrijwilligers.', 'Tijdens zo’n avond kunnen de gasten zich met van alles vermaken. Er wordt muziek gedraaid, tv gekeken, er worden spelletjes gedaan, of de mensen zitten gewoon gezellig te kletsen. Eens in de maand wordt er een activiteit bedacht, zoals een playbackshow of kienavond.', 'Alle drie zijn ze het er over eens: “Deze mensen met hun beperkingen zijn goudeerlijk. Je ziet ze gewoon genieten op zo’n avond. De liefde en dankbaarheid die je voor je inzet terug krijgt maken het meer dan de moeite waard om hier je energie in te steken!”', 'Verhaal verteld op: 17-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1430-490-368-1.jpg', caption: 'Bezoekers en vrijwillgers van de vrijdagavondsoos in Het Spectrum: Ko, Leo, Gerrie, Bas, Hans Laurens, Berengere, jan (82 jaar), Berend, Sjaak, Henk, Peter, Jollanda, Jeannet, Gerard, Judith, Alfred, Wim, Marianne, Joke, Richard, Erik, Maria Vrijwilligers: Ineke, Hennie, Huub en Thijs (kleinzoon van Huub & Hennie)')],
    relatedSlugs: ['de-aardbeien-opera-3237', 'van-istanboel-naar-heemskerk-2349', 'de-buurtbus-een-heemskerks-sprookje-4205', 'gillende-sirenes-2829', 'ik-ben-het-ballenmeisje-1724', 'fietsles-in-de-zandkraai-3766'],
