  MemoryStory(
    slug: 'jeugdliefde-1639',
    title: 'Jeugdliefde??',
    narrator: 'Mieke Baltus',
    author: 'Tineke de Ruyter',
    theme: 'straat & buurt',
    neighbourhood: 'Duin tot Dorp',
    period: '1974 - 1980',
    intro: ['Mieke Baltus is een echte Heemskerkse, opgegroeid in het tuindersgebied van Heemskerkerduin. Daar heeft zij goede herinneringen aan.'],
    body: ['Ik ben een echte Heemskerkse, opgegroeid in het tuindersgebied van Heemskerkerduin, waar mijn ouders een tuindersbedrijf hebben.', 'Heemskerkerduin is een leuke streek om op te groeien, waar ik met veel plezier aan terug denk. Uiteraard moest ik wel, toen ik ouder werd, zoals de meeste andere tuinderskinderen af en toe mijn vader helpen in de tuin (zie foto), maar gedurende mijn lagere schoolperiode heb ik er altijd heerlijk kunnen spelen. Je had altijd wel speelkameraadjes. Met een hele groep kinderen uit de buurt speelden we uren op straat. En mochten we ons een keer vervelen dan was er altijd de Evelaer nog.', 'Dit buurtcentrum is in 1972 opgericht, en naast de peuterspeelzaal, waar bijna alle duinkinderen naar toe gingen, werden er ook veel activiteiten voor de schoolkinderen georganiseerd. Je kon er kookles krijgen of judo op woensdagmiddag. Maar in de schoolvakanties was het helemaal feest. Dan werd een \'speldorado\'-week georganiseerd; dat betekende de hele week spelletjes doen zoals levend stratego of knutselen.', 'En dan de topper: de kampweek. De tuinders konden zich meestal niet in de zomertijd vrij maken om op vakantie te gaan, en daarom gingen alle kinderen (volgens mij ging écht iedereen) ieder jaar met een bus op kamp. Zo zijn we wel eens in Velp geweest of in Steensel. Het leuke is, dat ik zo’n kampweek toen al samen met mijn huidige echtgenoot heb doorgebracht. Hij is ook een duinkanter, dus ging ook mee, maar veel belangstelling voor elkaar hadden we toen nog niet. Hij zat een klas lager dan ik, dus nog een broekie! En ik maakte op hem ook totaal geen indruk. Gelukkig is dat later goed gekomen. Toen hadden we wél belangstelling voor elkaar…'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1644-490-685-1.jpg', caption: 'Mieke Baltus in actie tijdens een jeugdkamp van de Evelaer')],
    relatedSlugs: ['eerste-deuntje-3046', 'verslaving-4346', 'snotneus-op-klompen-3154', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472', 'paasbest-5015'],
