  MemoryStory(
    slug: 'kamer-zoeken-4828',
    title: 'Kamer zoeken',
    narrator: 'Henk Reinders',
    author: 'Henk Reinders',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Hart van Heemskerk',
    period: '',
    intro: ['In 1956 kreeg ik een baan bij Hoogovens. Daar ik uit Zutphen kwam, gaf de afdeling personeelszaken mij een lijstje met adressen waar kamers te huur waren. Kort voordat ik bij Hoogovens ging beginnen, toog ik naar Heemskerk en Beverwijk om me van een onderkomen te verzekeren.'],
    body: ['Op een druilerige dag maakte ik op de motor de tocht van Zutphen naar hier.', 'Bij het eerste adres waar ik aanbelde, kreeg ik kortweg een afwijzend antwoord. Op naar het tweede adres. Daar had ik meer succes. Er was een gemeubileerde kamer te huur zonder verwarming. Daar wist ik wel raad op. Kort daarna meldde ik me weer op dat adres met mijn plunje en een ventilatorkachel. Mijn nieuwe hospita fleurde helemaal op toen ze me zag. Na mijn vertrek een dag of tien eerder had ze tegen haar man gezegd: ”Ik heb de kamer verhuurd aan een werknemer van Hooovens. Ik hoop maar dat het wat is, want hij zag er nogal onverzorgd uit”. Wat was het geval. De prut van de weg had bij mijn eerste bezoek zijn sporen achter gelaten op mijn motorkleding en op mijn gezicht. Bij het afzetten van mijn motorbril had ik schone plekken rondom mijn ogen maar de rest was groezelig. Ik begreep nu waarom ik bij de eerste kamer zo resoluut werd afgewezen. Kennelijk was de hospita van het tweede adres meer op haar intuïtie af gegaan.', 'Verhaal verteld op: 09-01-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4829-345-492-1.jpg', caption: 'Het gezicht van Henk Reinders onder de modder, na zijn motorrit van Zutphen naar Heemskerk.')],
    relatedSlugs: ['emigreren-of-werken-op-kasteelhoeve-2243', 'van-marquette-bos-naar-hoogoven-5-1280', 'merkwaardig-4870', 'graanteelt-2234', 'de-vrijheit-4702', 'fietsenmaker-2647'],
  ),
  MemoryStory(
    slug: 'kattenkwaad-in-de-antonio-morstraat-3437',
    title: 'Kattenkwaad in de Antonio Morstraat',
    narrator: '',
    author: 'Jetty Groeneveld',
    theme: 'straat & buurt',
    neighbourhood: 'Duin tot Dorp',
    period: '1960 - 1967',
    intro: ['Mijn jongste jaren speelden zich af in de Antonio Morstraat. We voetbalden veel in de plantsoentjes in onze straat. \'s Ochtends om zeven uur stond je op om te voetballen. Je moeder riep je dan om acht uur binnen, want je moest nog eten voor je naar school ging.'],
    body: ['Behalve voetballen haalden we natuurlijk ook rottigheid uit. Langs de huizen liep een ventweg. Daar kwamen de bakker en de melkboer. De melkboer had zijn melk los in een bus, waar hij de melk met een litermaat uitschepte. In de plantsoentjes groeiden bosjes met bessen. Wij plukten dan die bessen en deden ze stiekem in de melkbus.', 'In de tijd van Ard Schenk en Kees Verkerk gingen we rolschaatsen op het pleintje. De wieltjes maakten veel lawaai op de straat. De buurtbewoners vonden dat vervelend. Die terroriseerden dat door duivenvoer te strooien. Dan konden wij niet meer rolschaatsen.', 'Het ventpad gebruikten we ook als er Tour de France was. Keihard racen met je fiets. Dat was levensgevaarlijk, want er waren ook poortjes waar wel eens iemand uitkwam. Daar zat je dan bovenop.', 'Aan de overkant woonde iemand die een rode auto had. Die parkeerde hij waar wij altijd voetbalden. Dat werd dus oorlog! Je begrijpt dat onze bal vaak \'per ongeluk\' tegen die auto kwam.', 'Ik herinner me nog Dick Bouman. En de familie Herf. Dat waren Indische mensen. Ze hadden een aap in huis. Er woonde bij hun ook een meneer, ome Jan. Die wist veel van voetbal. Hij zei tegen mij: "Ik krijg een kaartje van je als je profvoetballer wordt bij Ajax."', 'Casse is er geboren. Die is nu Deken van Haarlem. Ik was bevriend met zijn broertje Ruud. Maar er zijn ook mensen die minder goed terecht zijn gekomen. Zo loopt dat uiteen. Er leefde van alles in die buurt.', 'Verhaal verteld op: 28-02-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3503-490-474-1.jpg', caption: 'Margreet en Jan-Willem op de slee; Aad kijkt toe.')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'eerste-deuntje-3046', 'thuis-onder-de-toren-van-de-lau-1472', 'rennende-mensen-1726', 'paasbest-5015', 'het-witte-huisje-5783'],
