  MemoryStory(
    slug: 'kerkbezoek-voor-de-sint-4420',
    title: 'Kerkbezoek voor de Sint',
    narrator: 'Piet Castricum',
    author: 'Jeanne Castricum',
    theme: 'feesten & evenementen',
    neighbourhood: 'Hart van Heemskerk',
    period: '1935 - 1942',
    intro: ['De Sint Jozefschool werd in mijn jonge jaren altijd op 6 december verblijd met een bezoek van Sinterklaas. In die tijd waren het Sintbezoek en kerkgang nog nauw met elkaar verbonden.'],
    body: ['In die tijd noteerde de onderwijzer van de klas elke dag de namen van degenen die \'s morgens naar de kerk waren geweest. Mijn naam stond daar niet vaak bij. Ik kwam uit een kruideniersgezin, \'t winkeltje van ome Jan\', en moest \'s morgen voor schooltijd eerst meehelpen met boodschappen klaarmaken en bezorgen bij de klanten. Met de transportfiets waar mijn hoofd als 11 jarig broekie net boven de vol geladen mand uitstak.', 'Met verlangen keek ik elk jaar uit of Sint mij ook eens een dik kerkboek zou brengen. \'Ora et labora\', bid en werk, luidde toch het gezegde? En ik had immers mijn best gedaan. De Sint kon dat toch weten.', 'Wat was de teleurstelling groot als ik weer het allerdunste boekje in ontvangst nam en de Sint zei: \'Meer naar de kerk gaan jongen.\' Zwarte Piet gaf me nog wel een hand en wat pepernoten. Maar het dunste kerkboekje bleef in mijn ogen een onverdiend cadeau.', 'Verhaal verteld op: 01-12-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4421-490-276-1.jpg', caption: 'De Sint in Heemskerk')],
    relatedSlugs: ['burgemeester-gesnapt-3463', 'eerste-deuntje-3046', 'dodenherdenking-5263', 'muziek-op-het-kerkplein-2298', 'radiotik-2888', 'lost-in-donkey-jazz-2327'],
