  MemoryStory(
    slug: 'kinderboerderij-4640',
    title: 'Kinderboerderij',
    narrator: 'Michelle Brondijk',
    author: 'Michelle Brondijk',
    theme: 'school',
    neighbourhood: 'Van Acker tot Burcht',
    period: '- 2007',
    intro: ['Op oudejaarsnacht werden we geschokt omdat de kinderboerderij in brand stond. De meeste mensen denken dat het vuur aangestoken is. Dat vinden we heel erg zielig en laf. Daarom heeft onze Anne Frankschool een actie gehouden.'],
    body: ['Kinderen van onze school gingen 4 buttons verkopen voor minstens vijftig cent. Er werden ook een heleboel eigen acties gehouden. Zoals gewoon langs de deuren en vragen of de mensen nog wat geld voor de kinderboerderij hadden en er werden flessen opgehaald en nog veel meer. In totaal werd er door deze school €3224,11 opgehaald.', 'De hele school ging het geld midden in de regen naar de kinderboerderij brengen. De beheerder Johan Gaarenstroom was heel erg blij met dit grote bedrag en beloofde dat er een hele mooie kinderboerderij gaat komen en dat de kinderboerderij voor de zomer klaar zal zijn. In de kinderboerderij komen: een kalf, een biggetje, een paard, geiten, schapen en lammetjes te staan.', 'Verhaal verteld op: 21-01-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4683-480-360-1.jpg', caption: 'Directeur Thom de Boer van de Anne Frankschool overhandigt het door de leerlingen verzamelde geld aan beheerder Johan Gaarenstroom')],
    relatedSlugs: ['eerste-deuntje-3046', 'paasbest-5015', 'snotneus-op-klompen-3154', 'slapen-tussen-kippengaas-1992', 'dodenherdenking-5263', 'rennende-mensen-1726'],
  ),
  MemoryStory(
    slug: 'klanten-winnen-1344',
    title: 'Klanten winnen',
    narrator: 'Piet Tromp',
    author: 'Kees van Duivenvoorde',
    theme: 'school',
    neighbourhood: 'Duin tot Dorp',
    period: '1925 - 1931',
    intro: ['Ik werd in 1919 geboren in het huisje aan de Voorweg 6. Veel huizen stonden er niet in het Heemskerkerduin. Veel grond was nog weiland.'],
    body: ['Ik moest de ruim 3 kilometer naar de lagere school (St. Jozef) dagelijks te voet afleggen. Reeds om 7 uur in de ochtend ging ik lopend, gewapend met de stikkezak met brood richting dorp. Eerst moest de Heilige Mis bezocht worden. Omdat je te communie moest mocht je voor die tijd niets eten of drinken. Na de mis werd in school brood gegeten en ook tussen de middag werd meegebracht brood gegeten.', 'Ik liep samen met Gerrit Zonneveld en Cor Aardenburg naar school. Ik was een van de eersten die een fiets kreeg. Het was een kleine fiets. Ik was nog niet groot. De fiets was gekocht bij Dunneboer in Assendelft. Meester Gallee gaf toestemming om de fiets binnen in de school te stallen. Het was een kostbaar bezit. ‘s Winters als het echt koud werd viel het niet mee om tegen de oostenwind in naar school te lopen of te fietsen. Als je geluk had beschikte je over oorwarmers. Het was echt afzien op de kale vlakte.', 'Uiteraard liep een ieder op klompen. Bij het betreden van de kerk moesten de klompen uit en op kousenvoeten moest je verder. Jongens moesten direct bij binnenkomst de pet afzetten. Meisjes waren echter verplicht het hoofd wel te bedekken met doek of muts. Aan de communiebank werden de meisjes zonder hoofdbedekking overgeslagen.', 'In de duinen werd op een klein vlak stukje gevoetbald met de buurjongens. Om een echte leren bal te kopen werd gezamenlijk flink gespaard. Ik kon al wat centjes verdienen door de melkboer te helpen: als er ergens nieuwe bewoners kwamen wonen moest ik gaan vragen of zij klant wilden worden.', 'Verhaal verteld op: 01-07-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1360-425-319-1.jpg', caption: 'Het geboortehuisje van Piet Tromp')],
    relatedSlugs: ['snotneus-op-klompen-3154', 'het-witte-huisje-5783', 'verslaving-4346', 'de-vrijheit-4702', 'nonnenfrustratie-1658', 'dodenherdenking-5263'],
  ),
  MemoryStory(
    slug: 'koeien-aan-de-hoflaan-3222',
    title: 'Koeien aan de Hoflaan',
    narrator: 'Henk Altena',
    author: 'Henk Altena',
    theme: 'straat & buurt',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '2005 - 2006',
    intro: ['Als ik uit mijn raam kijk, zie ik vliegtuigen, treinen, auto’s, veel auto’s, motoren, brommers, fietsers, trimmers en wandelaars, met en zonder hond. En de nieuwbouw van de Broekpolder. Maar gelukkig ook nog weiland.'],
    body: ['Op dat weiland lopen koeien en die zijn eigendom van de broers Hoogewerf. Zij wonen in die mooie boerderij Oudt-Haerlem aan de Hoflaan, al sinds 1650. Nou ja, niet de broers, de familie Hoogewerf woont daar waarschijnlijk al zo lang.', 'Eerst waren er zo’n 50 koeien , maar ja, de boerderij raakte ingebouwd......het weiland wordt stadspark en de beide broers wat ouder.... dus begin 2005..... weg die koeien. Jammer, want die koeien maakten rare bokkensprongen, loeiden en werden vlak bij de weg gemolken, kregen daar ook kalfjes en dat was leerzaam en boeiend.', 'In januari 2006, op de avond van het buurtbeheer Zuidbroek-Oosterwijk vroeg ik de broers, hoe het was zonder de beesten. Eensgezind, maar verrassend, zeiden ze “lekker uitslapen, na zoveel jaren vroeg melken." Maar ook:“’t Zou toch wel leuk zijn, nog wat beesten om de deur." En gelukkig, er bleven een tiental kalfjes in de wei en die groeiden op tot pinken en daarna tot vaarzen en toen tot echte koeien .......zo gaat dat bij koeien! Die koeien kregen deze zomer weer kalfjes die weer de hele winter buiten blijven.........”worden zo sterke koeien” volgens de broers.', 'Sommige kalfjes zijn bruin, anderen zwart, maar ze hebben een kenmerk... witte koppen. Een fokkerstruc van de Hoogewerfs?', 'Midden in alle drukte kan ik toch van dat spul genieten! En denk je dan, zouden alle eerdergenoemde passanten ook wel eens opzij kijken? Bedenk dan wel....dit is uniek in 2006!', 'Verhaal verteld op: 15-12-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3208-490-368-1.jpg', caption: 'De koeien van de broers Hoogewerf in het weiland tussen de Hoflaan en de spoorlijn, met op de achtergrond de nieuwbouw van Broekpolder. 2006')],
    relatedSlugs: ['eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'rennende-mensen-1726', 'thuis-onder-de-toren-van-de-lau-1472', 'zitkuil-tevens-vijver-1326', 'paasbest-5015'],
  ),
  MemoryStory(
    slug: 'konijnen-en-kippen-in-de-patio-van-de-otterkolken-3069',
    title: 'Konijnen en kippen in de patio van de Otterkolken',
    narrator: '',
    author: 'Henritte Dekkers',
    theme: 'school',
    neighbourhood: 'Boven de Baandert',
    period: '1970 - 1990',
    intro: ['De Otterkolken is in het rijke bezit van een patio. In de loop der jaren is er veel in geploeterd!'],
    body: ['Het eerste jaar (1970) ging de zesde klas onder leiding van mijnheer Wiegmans aan het zaaien. De leerlingen konden kiezen uit radijsjes, worteltjes, maar ook loempiazaad, zure augurken en zelfs zoetzure augurkenzaad. Al snel kregen ze door dat dit wel heel vreemde zaden waren. Enthousiast gingen ze aan de slag. Ze waren dol op onkruid wieden en trokken rustig net opgekomen worteltjes weer uit de grond…', 'Het tweede jaar werd de patio omgetoverd in een bloemenzee en kwamen de eerste dieren. De ‘technische club’, bestaande uit handige vaders, timmerde de hokken en de konijnen kregen een waar paleis. Alleen ontsnapten ze regelmatig, groeven overal holletjes en verrasten iedereen met jonkies.', 'De ‘konijnentemmers’ uit klas 6 zorgden voor eten en ieder speelkwartier mochten uit iedere klas twee kinderen kijken en knuffelen.', 'Toen pastoor Van Stein in een bejaardenflat ging wonen, erfde de school al zijn krielkippen. De kinderen stonden de eerste ochtend in de gang en riepen: “Me hebbe kippen.”', 'Naast de ‘konijnentemmers’ kregen ook ‘kippenbeulen’ een belangrijke taak: Het eerlijk verdelen van de eitjes. Daarvoor moest wel eerst de hele patio worden uitgekamd, want die krieltjes deponeerden de eitjes op de vreemdste plekjes.', 'In 1973 kreeg ik van mijnheer Deen, hoofd van de Christelijke Anne de Vriesschool een krielhaan. Die werd door mijnheer Wiegmans onmiddellijk benoemd tot ‘Kip met de Bijbel’.', 'Naast deze hoogtepunten waren er helaas ook dieptepunten, toen in latere jaren de patio regelmatig bezoek kreeg van baldadige jeugd uit de omgeving. Ze klommen over het dak naar de binnentuin, maakten hokken open en hebben soms dieren mishandeld of zelfs doodgemaakt.Dit zorgde voor hevige verontwaardiging en furieuze reacties bij onze leerlingen. Noodgedwongen zijn we toen maar gestopt met het houden van dieren.', 'Verhaal verteld op: 14-03-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2607-490-426-1.jpg', caption: 'Dick Beentjes & Wim Moens')],
    relatedSlugs: ['dodenherdenking-5263', 'als-hond-en-kat-4339', 'lost-in-donkey-jazz-2327', 'paasbest-5015', 'nonnenfrustratie-1658', 'radiotik-2888'],
  ),
  MemoryStory(
    slug: 'kruimeltjesgehakt-1748',
    title: 'Kruimeltjesgehakt',
    narrator: 'Henriëtte Dekkers',
    author: 'Henritte Dekkers',
    theme: 'buren & vriendschap',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '1972 - 1977',
    intro: ['Van 1971 tot 1977 woonde ik op het Europaplein aan de Heemskerkse kant in een éénpersoonsflatje. Veel van de bewoners werkten net als ik in het onderwijs.'],
    body: ['\'s Avonds kookte iedereen zijn of haar eigen potje. Ongeveer tegelijkertijd ontdekten een aantal mensen dat samen eten veel gezelliger en handiger was. Zo ontstonden allerlei eetclubs. Het maximum was zo\'n 6 personen. Anders paste iedereen niet rond de tafel en het eten niet in de pan. Soms ruilden we van club zodat je weer eens andere tafelgenoten had. Een enkele keer aten we met z\'n allen samen. Als regel hadden we: wie kookt hoeft niet af te wassen en iedereen kookte wat hij/zij zelf lekker vond. Het was de tijd dat we het kruimeltjesgehakt uitvonden. Nu is dat heel gewoon: gehakt rul bakken, maar toen was het echt iets nieuws. Ook probeerden we voor het eerst vegetarische maaltijden uit en werden het champignons in plaats van vlees.', 'Na de Europapleinperiode hebben de eetclubs nog jaren lang bestaan; tot aan Alkmaar aan toe! Met veel mensen ben ik nog steeds bevriend en soms houden we een eetclubreünie. Ik denk dat in de loop van de jaren wel 20 tot 30 mensen hebben meegedaan en ik kijk er nog met plezier aan terug.', 'Verhaal verteld op: 15-11-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1762-490-341-1.jpg', caption: 'In 1975 heb ik deze foto vanaf mijn balkon genomen.')],
    relatedSlugs: ['van-marquette-bos-naar-hoogoven-5-1280', 'zitkuil-tevens-vijver-1326', 'de-acht-zaligheden-1802', 'vier-op-een-rij-4168', 'een-leven-lang-op-de-planken-5388', 'een-biertje-2827'],
  ),
  MemoryStory(
    slug: 'kunstwerk-op-de-patio-van-de-otterkolken-4160',
    title: 'Kunstwerk op de patio van de Otterkolken',
    narrator: '',
    author: 'Henritte Dekkers',
    theme: 'school',
    neighbourhood: 'Van Acker tot Burcht',
    period: '1970',
    intro: ['In het kader van de ‘1-procent-kunst-regeling’ mocht de nieuwe school opgesierd worden met een kunstwerk. Het team koos voor Nico Betjes, die al verschillende kunstwerken bij Heemskerkse gymzalen had gemaakt. Het hoofd van de school, meneer Wiegmans wilde graag een kunstwerk waar de kinderen ín en óp konden en ze contact konden hebben met water. Het moest vooral geen passief kunstwerk zijn om alleen maar naar te kijken.'],
    body: ['Nico Betjes werd hierdoor geïnspireerd tot het maken van een stelsel van bekkens, waarbij opgepompt water terugkeerde in een vijver. De kinderen konden daar de watervallen zien en voelen. Alles wat leefde en zwom in dat vijvertje trok hun aandacht. Om de kinderen een gezellige zitplek te bieden, maakte Nico er een grote kring van bielzen aan vast. De zitkring is jarenlang door de klassen gebruikt om kringgesprekken te houden, voor te lezen, te zingen, toneel te spelen enz. Met hulp van de technische club is het kunstwerk in de patio gebouwd en voorzien van stroomtoevoer voor het pompje. De technische club was een groep vaders die wekelijks op school kwamen om allerlei praktische wensen die we hadden voor elkaar te boksen. Bij toerbeurt werd iedere ochtend het pompje van het kunstwerk aangezet tot na schooltijd, zodat het klaterende water de hele dag te horen was. Helaas is de pomp verschillende keren kapot gemaakt of gestolen door vandalen, die via het dak in de patio klommen. Toch zitten er nog altijd salamanders en kikkers in de vijver en zijn de kinderen daar tot de dag van vandaag daar niet bij weg te slaan.', 'Verhaal verteld op: 01-01-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4163-446-762-1.jpg', caption: 'Nico Betjes aan het werk voor het kunstwerk in de patio van de Otterkolken.')],
    relatedSlugs: ['dodenherdenking-5263', 'lost-in-donkey-jazz-2327', 'paasbest-5015', 'nonnenfrustratie-1658', 'ik-timmerde-hem-op-zijn-neus-1421', 'sport-en-spel-bij-de-cornelis-geelvinckstraat-5154'],
  ),
  MemoryStory(
    slug: 'landgoed-6201',
    title: 'Landgoed',
    narrator: '',
    author: 'Henritte Dekkers',
    theme: 'bekende personen',
    neighbourhood: 'Duin tot Dorp',
    period: '1972 - 2009',
    intro: ['Dit is geen volkstuin maar een landgoed. Ik tuinier niet speciaal voor de planten maar ik maak een sfeer. In mijn jeugd in Alkmaar wilde ik al een tuin en begon met de andijviestronken van mijn moeder te planten. Helaas werden er de vloerkleden over uitgeklopt, dus dat werd niet zoveel bijzonders.'],
    body: ['In 1972 begon ik hier op Bickershof. Eigenlijk toevallig, omdat mensen mij vroegen of dit niet iets voor mij was. Ik begon met koolplanten waarvan sommigen het niet deden. Iemand raadde mij DDT aan maar dat vertrouwde ik niet. In die tijd las ik een boek over biologisch tuinieren van Pieter Boxma. Daarna kwamen de boeken van Rudolf Steiner. Dat was een logisch vervolg. Een wereld ging voor me open. Ik wilde \'weten\'.', 'Nu heb ik twee tuinen met een grote waterpartij met waterlelies en kikkers. Op mijn tuin staat een huisje en een orangerie. Alles heb ik gemaakt van wat de mensheid weggooit. Ik ben hier elke dag met veel plezier om van alles te doen en ook om mensen te ontmoeten en onze gedachten met elkaar te delen.', 'Iedereen is hier altijd van harte welkom. Tijdens de afgelopen open dagen hoorde ik iemand zeggen: "Annie, kom gauw. Hier kan je op avontuur!" Ja, 87 jaar en dan nog op de fiets!', 'Verhaal verteld op: 01-09-2009'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.6239-490-368-1.jpg', caption: 'Albert bezig in zijn tuin op Bickershof')],
    relatedSlugs: ['verslaving-4346', 'de-aardbeien-opera-3237', 'het-witte-huisje-5783', 'een-grensgeval-1868', 'merkwaardig-4870', 'ezel-met-duinkater-2036'],
  ),
  MemoryStory(
    slug: 'lassie-lasee-3654',
    title: 'Lassie Lasee',
    narrator: '',
    author: 'Leny Gigengack',
    theme: 'straat & buurt',
    neighbourhood: 'Hart van Heemskerk',
    period: '1964',
    intro: ['In de jaren zestig mochten honden nog los lopen op straat. Niemand in Heemskerk stoorde zich daaraan.'],
    body: ['We woonden al een poosje in Heemskerk; het zal 1964 zijn geweest. Uit het Kerbert Asiel hadden we een hele lieve, levendige hond gehaald, die bij de eerste kennismaking onze zoon in zijn hand beet, nou meer hapte. Hij was echt lief met de kinderen en hij heette Lassie.', 'In deze tijd mochten honden nog op straat worden losgelaten en Lassie maakte daar dankbaar gebruik van. Soms was hij even weg, maar een andere keer kon het zijn, dat hij uren wegbleef. In het dorp kenden veel mensen hem en het gebeurde wel, dat er een politieauto bij ons voor de deur stopte. Vrolijk sprong Lassie er dan uit; de agenten hadden hem zien lopen op hun route en brachten hem maar even thuis. Lassie was niet zo moeilijk, die vond zo\'n ritje zelfs wel leuk!', 'Nog een voorbeeld van het kleindorpse van Heemskerk.', 'Ik had een "nieuwe" auto, een Triumph- Spitfire, die ik veel gebruikte. Omdat hij nogal opvallend was, werd hij door veel mensen herkend. Op een dag bracht de politie onze Lassie weer eens thuis en de agent zei:" Ik vind het jammer voor u hoor, maar u heeft een bon. We waren een snelheidscontrole aan het uitvoeren en u kwam langs ons en reed echt te hard; wel 55 km! Dus binnenkort zult u wel een boete krijgen per post."', 'Aardig toch hè, dat je dat in die tijd nog persoonlijk te horen kreeg!', 'Verhaal verteld op: 18-06-2007'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3735-490-350-1.jpg', caption: 'Zoon en hond Lassie van de familie Lasee.')],
    relatedSlugs: ['thuis-onder-de-toren-van-de-lau-1472', 'eerste-deuntje-3046', 'verslaving-4346', 'snotneus-op-klompen-3154', 'een-grensgeval-1868', 'rennende-mensen-1726'],
  ),
  MemoryStory(
    slug: 'lekkere-rooie-1426',
    title: 'Lekkere Rooie',
    narrator: '',
    author: 'Kees van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Duin tot Dorp',
    period: '1957',
    intro: ['Heemskerk was tot begin jaren zestig van de vorige eeuw landelijk bekend op het gebied van de aardbeienteelt. Vrijwel alle tuinders in Heemskerk hadden diverse hoeken(percelen) met aardbeien liggen.50 % van onze tuin aan de Voorweg stond vol met aardbeien'],
    body: ['Was de opbrengst van de aardbeien goed dan had ook de plaatselijke middenstand een goede omzet. Het was niet altijd rozengeur en maneschijn. Bij een koud voorjaar versteenden de vruchten en bij veel regen of een fikse onweersbui in het oogstseizoen rotten de vruchten weg.', 'Jong en oud moest helpen bij de oogst. Als kind van 5 á 6 jaar moest ik voor en na schooltijd al helpen de volgeplukte sloffen naar de kant te brengen en in de daarvoor bestemde kratjes te zetten. Je kon al snel een greppelkantje plukken. Vanaf je 10e jaar kregen de tuinderskinderen ‘plukverlof’. De scholen waren dan vrijwel leeg. Of die kinderen dat altijd even leuk vonden is weer wat anders. Was er eindelijk eens het schoolreisje, werd er doodleuk op school gezegd dat je niet mee mocht omdat je aardbeien moest plukken.', '’s Morgens om 4.00 uur was alles nog erg nat en koud. Beschermende waterdichte kleding had men niet en binnen 10 minuten was je geheel doorweekt. Soms was het zo koud dat je de vruchten er niet meer afkreeg en even moest lopen of het huis in gaan om de handen te warmen. Later op de dag kon het tussen de veel aanwezige hagen weer erg warm worden. In de middag werden de aardbeien naar de veiling aan de Breestraat in Beverwijk gebracht en steeg de spanning om wat de opbrengst zou zijn. Vaak viel het mee doch er waren ook tijden dat de plukkosten bijna niet eens betaald werden. Kortom het was niet altijd rozengeur en maneschijn. Maar lekker waren die vruchten wel. Lekkere Rooie ik hou zo van jou.', 'Verhaal verteld op: 20-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1428-473-314-1.jpg', caption: 'Vader Nelis van Duivenvoorde met dochters Ria en Corrie en zoon Kees')],
    relatedSlugs: ['emigreren-of-werken-op-kasteelhoeve-2243', 'merkwaardig-4870', 'landgoed-6201', 'fietsenmaker-2647', 'een-grensgeval-1868', 'ezel-met-duinkater-2036'],
  ),
  MemoryStory(
    slug: 'libanese-in-heemskerk-2976',
    title: 'Libanese in Heemskerk',
    narrator: 'Rita Khandalaft',
    author: 'Luus de Wit',
    theme: 'vrijwilligerswerk',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '1996 - 2006',
    intro: ['Rita Kandalaft komt uit Libanon en woont al bijna 10 jaar op de Luxemburglaan. Haar naam Rita klinkt behoorlijk Nederlands.'],
    body: ['“Dat komt door mijn katholieke achtergrond. Ik ben gedoopt als Catharina.', 'Ik woon samen met mijn twee kinderen op de derde verdieping, hoog boven de grond in een rustige groene buurt. Dat is zo anders dan mijn leven in Libanon. Ik kom uit Achrafieh, bij Beirut en groeide op in een oorlogssituatie. Dag in dag uit voelde ik angst. Ik was soms bang op straat als ik van of naar school liep en ik schuilde samen met onze buren regelmatig in de beveiligde kelder onder ons flatgebouw.', 'Op school deden we veel aan sport. Gelukkig wel, want na school was ik voornamelijk binnen. Lekker onbezorgd buiten spelen, zoals mijn kinderen hier doen, was er niet bij.', 'Ik haal mijn kinderen meestal op uit school. Het contact met andere ouders is leuk en belangrijk om de taal steeds beter te leren. Ik was eerst vrijwilliger bij buurtcentrum de Globe. Daar had ik contact met allerlei mensen. Nu help ik bij de peuterspeelzaal de Karekiet in ’t Tweespan. Het contact met de ouders van de peuters is ook goed voor mijn taal.', 'In Libanon gaf ik pianoles aan jonge kinderen. Dat zou ik hier ook graag willen doen, maar mijn diploma is hier niet geldig. Gelukkig kon ik oefenen bij de muziekschool en met hun hulp heb ik nu een elektrische piano, zodat ik kan blijven spelen. Ik zou graag van iemand de Nederlandse termen leren voor het pianospelen.', 'Ik kan me niet voorstellen ooit terug te gaan naar Libanon. Ik voel me veilig en vrij in Nederland en probeer hier mijn leven op te bouwen. Ik hoop dat de dromen die ik heb hier werkelijkheid worden.”', 'Verhaal verteld op: 23-05-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2986-490-370-1.jpg', caption: 'Rita tijdens de woensdagmiddaginstuif in buurtcentrum de Globe.')],
    relatedSlugs: ['slapen-tussen-kippengaas-1992', 'het-witte-huisje-5783', 'de-aardbeien-opera-3237', 'zakje-kras-snoepje-van-de-week-3344', 'rustig-op-straat-spelen-2106', 'hondje-2641'],
  ),
  MemoryStory(
    slug: 'lost-in-donkey-jazz-2327',
    title: 'Lost in Donkey Jazz',
    narrator: 'Linda van Zeijl',
    author: 'Linda van Zeijl',
    theme: 'feesten & evenementen',
    neighbourhood: 'Hart van Heemskerk',
    period: '- 2006',
    intro: ['Er komt een duister figuur met een hoed voor je staan, het liefst geef je hem een zetje, maar dat doe je niet als Jazzganger, dan ben je beleefd en sociaal.'],
    body: ['Lekker jezelf kwijt raken in the mood van Jazz, met je hoofd mee schudden, je benen proberen met de schommelende maat van de piano mee te gaan. Peukie in je mond, halfvol glas whisky in je hand.', 'Er komt er een duister figuur met een hoed voor je staan, het liefst geef je hem een zetje, maar dat doe je niet als Jazzganger, dan ben je beleefd en sociaal. Je besluit maar naast hem te gaan staan. Terwijl je begint te wurmen, kijkt de grijze man je aan en tikt aan de rand van zijn zwarte hoed. Je geeft een knipoog terug en verdwijnt weer in de muziek.', 'Een giga contrabas komt naar voren met een man eraan gehangen, dududududu, hoog, laag, langzaam, snel. De drummer zonder haar valt hem bij. Toeng toeng toeng. De saxodulfer, de pianist….. aaahhhh het hoogtepunt bereikt!', 'Snel neem je een slok van je Johnny Walker, een haal van je peuk, daar kun je jezelf goed achter verbergen.', 'Je kijkt speels om je heen, het Jazzcafé is vol en rokerig. Interessante mannen met doorleefde koppen staan vol overgave te luisteren naar de Jazzy noten die er om hun hoofd worden geslingerd. Vrouwelijke dames met rode lipstick, kijken smachtend naar de transpirerende muzikanten en proberen met zwoele blikken oogcontact te maken. Verderop zit een groep jongeren met kleppetjes op, foto’s te maken met hun hightech mobieltjes van een zwetende drummer en adhd pianist.', 'En ik? Ik sta te genieten in mijn zwarte jurkje en met een zinnelijke blik probeer ik contact te maken met de barman! Ik bestel twee whisky en geef de man naast mij een rondje, zijn hoed gaat even van zijn hoofd, krijg een knikje en een sigaret. Samen in the mood, swingen, nippen en roken we de middag door.', 'Mezelf kwijtgeraakt in de klanken van Donkey Jazz………', 'Verhaal verteld op: 12-03-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2329-490-392-1.jpg', caption: 'Hans Dulfer')],
    relatedSlugs: ['hard-house-in-cafe-nijman-1854', 'het-doek-is-gevallen-4280', 'als-hond-en-kat-4339', 'radiotik-2888', 'een-biertje-2827', 'een-leven-lang-op-de-planken-5388'],
  ),
  MemoryStory(
    slug: 'luchtvaart-in-heemskerk-2654',
    title: 'Luchtvaart in Heemskerk',
    narrator: 'Nico Sinnige',
    author: 'Kees van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Duin tot Dorp',
    period: '1937',
    intro: ['Ook voor W.O. II had Heemskerk al luchtvaartpionoers'],
    body: ['Luchtvaart in Heemskerk', 'In mijn jonge jaren trachtte ik de kost te verdienen als fietsenmaker en elektricien We spreken over de begin jaren dertig. Van Jan Eeltink kocht ik een oude Harley Davidson 2-cylinder motorfiets voor Fl 25,- Hier heb ik flink me geëxperimenteerd en er een 1-cylinder van gemaakt. De liefde voor de motor duurde niet lang. Op een dag kwam Jan Glorie langs. Hij ventte met petroleum. Eerst met de hondenkar en later met een bakfiets. Hij woonde aan de Rijksstraatweg, hoek Kleine Houtweg. Hij vertelde dat hij een vliegtuig aan het bouwen was en nog naar een motor zocht voor dat ding. Met zijn weinige gereedschap had hij al een frame in elkaar gezet op twee bakfietswielen. Uit een balk had Jan een propeller gemaakt, handmatig met beitsen en gutsen. De vleugels konden er pas aan gezet worden als het toestel naar buiten zo komen. De schuur was niet zo groot. Als eerst de motor met de propeller maar goed werken komt alles wel goed, zei Jan. Start en landingsbaan had Jan bedacht op de net geasfalteerde Noorderlaan, (Marquettelaan). Ik start hier bij de Rijksstraatweg en vlieg dan over Marquette en draai dan om weer te landen. Na lang werken en de nodige problemen zaten motor en propeller op het frame gemonteerd. Ik waarschuwde nog dat de propeller het geheel naar voren zou treken en tegen de schuurwand zou werpen. Jan zag daar geen probleem in. Ik heb alles goed vast gezet. De motor werd gestart en op toeren gebracht. Het geheel wilde vooruit maar kon niet. Het kon alleen naar beneden. Met een daverende klap sloeg alles tegen de grond. De propeller was aan gruzelementen en Jan’s droom lag in duigen', 'Verhaal verteld op: 15-06-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.2657-490-368-1.jpg', caption: 'In deze schuur bouwdw Jan zijn vliegtuig')],
    relatedSlugs: ['emigreren-of-werken-op-kasteelhoeve-2243', 'merkwaardig-4870', 'lost-in-donkey-jazz-2327', 'landgoed-6201', 'fietsenmaker-2647', 'een-grensgeval-1868'],
  ),
  MemoryStory(
    slug: 'merkwaardig-4870',
    title: 'Merkwaardig',
    narrator: 'Freek Stammes',
    author: 'Loes Sprengers',
    theme: 'straat & buurt',
    neighbourhood: 'Duin tot Dorp',
    period: '1936 - 2008',
    intro: ['Merkwaardig is het verkooppunt van curiosa naast het huis op Marquettelaan nummer 28, gelegen aan de demontabele rotonde. Freek Stammes woont er al zijn hele leven.'],
    body: ['Zijn ouders hebben het huis laten bouwen. Zo eentje met voor- en achterkamer gescheiden door schuifdeuren, compleet met bedstede. De keuken het centrale woonpunt.', 'Een tuindersgezin met bunders land tot aan de Diepenbrockstraat en grenzend aan het grondgebied van landgoed Marquette.', 'Vader Stammes overleed veel te vroeg. Het gezin moest verder, oorlog dreigde. Er kwamen kostgangers in huis die heel weinig hadden. Moeder heeft nog van een vlag ondergoed voor hen gemaakt. Opoe woonde in de voorkamer. Geregeld kwam er een man met een accordeon langs. Dat was gezellig, werd er in huis gedanst. In de schuur stonden paarden van de Duitsers die Kasteel Marquette bezet hielden tijdens de oorlog.', 'Nu zijn de tuinderijen vervangen door woningbouw en is de grenslijn met het landgoed de Mozartstraat geworden. De bloemenhandel is geminimaliseerd tot wat verkoop bij het huis. Zo af en toe kwam er een kabouter bij de bloemen te staan en telkens wat meer dierenfiguren. Een merkwaardig assortiment.', 'Freek voelt zich prima op deze plek en gaat er niet vandaan. Hij heeft naast dit alles zijn sporen verdiend als kunstfluiter en menig prijs in de wacht gesleept. Samen met De Klavierschippers speelde hij bij feestelijke gelegenheden. Een muzikale leefstijl.', 'Nog steeds is de keuken het centrale punt in huis. Vanuit het keukenraam kan hij zijn merkwaardige handel bij die merkwaardige rotonde goed overzien.', 'Verhaal verteld op: 02-02-2008'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4930-490-368-1.jpg', caption: 'Het huisje van de familie Stammes in vroegere tijden.')],
    relatedSlugs: ['eerste-deuntje-3046', 'een-grensgeval-1868', 'snotneus-op-klompen-3154', 'emigreren-of-werken-op-kasteelhoeve-2243', 'thuis-onder-de-toren-van-de-lau-1472', 'rennende-mensen-1726'],
