  MemoryStory(
    slug: 'met-10-000-gulden-op-de-bagagedrager-1452',
    title: 'Met 10.000 gulden op de bagagedrager',
    narrator: 'Josephien Wagter',
    author: 'Marianne van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Hart van Heemskerk',
    period: '1967',
    intro: ['Het is nu niet meer voor te stellen. Toen ik tussen 1965 en 1970 bij de PTT werkte werden allerlei berekeningen nog handmatig gedaan.'],
    body: ['Lange lijsten van uitbetalingen van de SVB (A.O.W.) of geldstortingen op diverse girorekeningen werden uit het hoofd opgeteld. Achter het loket werden deze lijsten met een telmachine gecontroleerd door de chef geldzaken.', 'Eens in de maand kwamen er Spaanse of Italiaanse gastarbeiders, werkzaam bij de Hoogovens per postwissel geld over maken naar hun familie. De desbetreffende bedragen rekenden wij dan (ook handmatig) om in peseta’s of Italiaanse lires. De kas moest op het eind van de dag op de cent af kloppen en kastekorten moest je uit eigen zak betalen. Zorgvuldigheid was dus geboden. Toch was het een sport om een lange rij zo snel mogelijk weg te werken.', 'Ik werkte soms ’s morgens in Beverwijk en ’s middags in Heemskerk (mijn standplaats). Op een dag kwam er een noodkreet vanuit Heemskerk. Daar hadden ze honderdjes nodig. Aangezien ik daar ’s middags toch heen moest kon ik mooi een pakje honderdjes meenemen. Een pakje was 10.000 gulden. Dat ging in mijn handtas achter op de Solex. Maarrrrrr… eerst even langs mijn moeder die zo’n bedrag nog nooit bij elkaar had gezien. Ik verdiende immers ongeveer 250 gulden bruto per maand.', 'Verhaal verteld op: 05-06-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1457-425-319-1.jpg', caption: 'Achter op de bagagedrager ging mijn damestasje met 10.000 gulden.')],
    relatedSlugs: ['emigreren-of-werken-op-kasteelhoeve-2243', 'van-marquette-bos-naar-hoogoven-5-1280', 'merkwaardig-4870', 'graanteelt-2234', 'de-vrijheit-4702', 'fietsenmaker-2647'],
