  MemoryStory(
    slug: 'werken-voor-de-huur-1450',
    title: 'Werken voor de huur',
    narrator: 'Piet Tromp',
    author: 'Kees van Duivenvoorde',
    theme: 'werk & werkloosheid',
    neighbourhood: 'Duin tot Dorp',
    period: '1930 - 1934',
    intro: ['Piet Tromp moest al heel jong werken om bij te dragen aan het levensonderhoud.'],
    body: ['Direct na het doorlopen van de lagere school moest Piet Tromp gaan werken. Piet woonde op Voorweg 6 (nu is dat no 26). Armoede alom en wat extra geld was welkom. Aan de overkant van de weg was zijn eerste baas. De heer Beentjes, bijgenaamd ‘De Patroon’. Naast tuinderij had deze baas ook nog wat koeien. Dit gaf melkopbrengst en mest voor de tuin.', 'Spitten in de winter en in de zomer de onvermijdelijke aardbeien. Er werd wel met acht mensen geoogst in de aardbeien. Algemeen gebruikelijk was het ras Amazone. Rondtrekkende zigeuners kwamen vaak helpen bij de oogst. Ook waren er doperwten en een speciaal soort, de ‘Raspers’. Deze smaakten heerlijk en plukten gemakkelijk. Uiteraard allemaal handwerk.', 'Ook op zaterdag werd er tot 18.00 uur gewerkt. De verdiensten waren fl 2,50 per week. In de avonduren werd nog extra gewerkt om 25 of 30 cent extra te verdienen voor de Volksfeesten. Als Piet zijn loon op zaterdag ontvangen had gaf hij dit thuis aan zijn moeder. Deze kon dan met dat geld weer terug naar ‘De Patroon’ omdat die de eigenaar was van de woning van Tromp. De huur bedroeg F2,50 per week. Later ging Piet bij een andere tuinder werken, Arie Docter. Deze tuinder had al snel een kas.', 'Ook werd er veel op ‘rabat’ geteeld, een smalle strook grond aan de noordkant afgeschermd met planken of blikken platen. Door de luwte en de extra zonnewarmte kon men dan eerder oogsten. Deze primeur groenten brachten extra geld op. Zoals zoveel duinkatten ging Piet ook \'s avonds en \'s nachts de duinen in om wat strikken te zetten en daarin konijnen te vangen. Deze buit werd afgeleverd bij Piet ’de Bok’ aan de Oostersteng. Weer een paar centen extra.', 'Verhaal verteld op: 28-04-2005'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.1454-425-295-1.jpg', caption: 'Piet kan nog steeds niet stilzittten')],
    relatedSlugs: ['verslaving-4346', 'slapen-tussen-kippengaas-1992', 'emigreren-of-werken-op-kasteelhoeve-2243', 'van-marquette-bos-naar-hoogoven-5-1280', 'de-vrijheit-4702', 'hondje-2641'],
