  MemoryStory(
    slug: 'witte-en-bruine-school-4220',
    title: 'Witte en bruine school',
    narrator: 'Toth Romeijn',
    author: 'Marianne van Duivenvoorde',
    theme: 'verdwenen plekken',
    neighbourhood: 'Duin tot Dorp',
    period: '1970',
    intro: ['Ik neem al heel wat jaren deel aan activiteiten van het buurthuiswerk. Als kind begon ik bij de voorloper van buurthuis de Werf. Dat stond aan de Jan Ligthartstraat waar nu Heemswijk is. Een beetje verscholen en daarachter alleen maar landerijen.'],
    body: ['Het was een club met allerlei activiteiten en het fijnste was eenmaal per maand het volksdansen. Na onze verhuizing naar De Maer ben ik doorgegaan met volksdansen en toen dat werd opgeheven in de Schuilhoek, ben ik Country Line dancing gaan doen.', 'Ik zat op kleuterschool Bartje aan de Jacob Marisstraat, naast twee katholieke kleuterscholen. Wij zeiden altijd de witte en de bruine, naar de kleuren die ze hadden. Die bruine hoorde bij de Maerten van Heemskerck school. Dat waren noodgebouwen en helemaal aan het eind had je de Anne de Vriesschool. Bartje hoorde daarbij en deze twee gebouwen waren beide van steen. Nu ik in een rolstoel zit kan ik jammer genoeg mijn danshobby niet meer beoefenen. 3D knippen is een fijne hobby die is overgebleven. Jammer dat ik geen club kan vinden om dat in groepsverband te doen.', 'Verhaal verteld op: 16-09-2006'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.4222-490-368-1.jpg', caption: 'Dansen met rolstoel valt niet mee, vindt Toth Romeijn')],
    relatedSlugs: ['eerste-deuntje-3046', 'snotneus-op-klompen-3154', 'merkwaardig-4870', 'droom-spat-uiteen-4305', 'thuis-onder-de-toren-van-de-lau-1472', 'varkenslapjes-in-de-sneeuw-3352'],
