  MemoryStory(
    slug: 'zakje-kras-snoepje-van-de-week-3344',
    title: 'Zakje Kras, snoepje van de week',
    narrator: 'Ineke Haaijer Duin',
    author: 'Ineke Haaijer',
    theme: 'straat & buurt',
    neighbourhood: 'Zuidbroek-Oosterwijk',
    period: '1962',
    intro: ['Elke week kregen wij een zakje Kras van tante Corrie de Wildt. Het was altijd spannend wat er in dat zakje snoep en in de toverschelp zat.'],
    body: ['Ik woonde op de Hoogdorperweg, precies tussen de boerderij van de familie Nol en de boerderij van Corrie en Niek de Wildt. De boerderij van de Wildt staat nu nog op de hoek van de Duitslandlaan. Binnenkort zal de slopershamer ook dit stukje jeugdsentiment doen verdwijnen.', 'Als kind kwamen we graag bij ome Niek en tante Corrie. De koeien stonden \'s winters op stal en soms mochten we helpen met koeien melken. Dat wil zeggen: helpen deed je met de handen in je zak, je mocht alleen kijken en soms de koeien een nieuwe liksteen geven. Kalfjes aaien mocht als je eerst je handen had gewassen. Je kreeg altijd een beker lauwe melk, vers van de koe. Tante Corrie was een schat van een mens: altijd vrolijk en altijd druk in de weer met de dieren en de schoonmaak. In de keuken rook het altijd naar groene zeep. Ik herinner mij nog steeds haar blozende, rode wangen, vooral als ze op de fiets zat. Ze kocht voor de jonge buurkinderen altijd een zakje Kras bij het buurtwinkeltje van Piet van Riesen in het dorp. In dat snoepzakje zat altijd een toverschelp, die in het water openging en dan kwam er een bloem of een visje uit. Het zakje Kras was altijd een van de hoogtepunten in de week! Als we tante Corrie terug zagen fietsen uit het dorp, moesten we wel even met een smoesje naar haar toe...Corrie en Niek hadden zelf geen kinderen. Wel logeerde er regelmatig een jongen uit Zwolle, die heel goed kon schilderen. Hij was een stuk ouder dan de kinderen uit de buurt. Tante Corrie noemde hem \'mijn kunstenmaker\'. Snapten wij niets van, hij deed geen kunsten, hij schilderde alleen maar...'],
    figures: [MemoryFigure('https://www.historischekringheemskerk.nl/Geheugen/geheugenvanheemskerk/image/1036.3349-490-368-1.jpg', caption: 'de boerderij op de Hoogdorperweg, hoek Duitslandlaan.')],
    relatedSlugs: ['thuis-onder-de-toren-van-de-lau-1472', 'eerste-deuntje-3046', 'verslaving-4346', 'snotneus-op-klompen-3154', 'een-grensgeval-1868', 'rennende-mensen-1726'],
